window.FRAGEN=[{"id":"ar-01","typ":"single","frage":"Bis wann muss ein Taxiunternehmer einem neuen Fahrer die Angaben zu Arbeitsentgelt und Arbeitszeit schriftlich aushändigen?","optionen":["Spätestens am ersten Arbeitstag","Innerhalb von 7 Tagen","Innerhalb eines Monats","Nur wenn der Fahrer danach fragt"],"richtig":0,"erklaerung":"Namen, Entgelt und Arbeitszeit gehören zu den Angaben, die spätestens am ersten Tag der Arbeitsleistung vorliegen müssen. Im Personenbeförderungsgewerbe auf Papier mit Unterschrift.","quelle":"§ 2 Abs. 1 NachwG","lc":true,"lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-02","typ":"zahl","frage":"Ein Taxifahrer arbeitet im Februar 2026 insgesamt 150 Stunden, inklusive Wartezeiten am Taxistand. Er bekommt 38 % vom Netto-Umsatz von 5.000 €. Wie viel muss der Unternehmer mindestens zahlen (brutto)?","richtig":2085,"einheit":"€","tol":0.5,"loesung":"Umsatzlohn: 38 % × 5.000 € = 1.900,00 €\nMindestlohn: 150 h × 13,90 € = 2.085,00 €\n→ Mindestens 2.085,00 € (der höhere Betrag)","erklaerung":"Der Mindestlohn (13,90 € ab 2026) muss für jede Arbeitsstunde erreicht werden. Standzeiten in Bereitschaft zählen mit.","quelle":"§ 1 MiLoG, MiLoV5","lc":true,"lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-03","typ":"multi","frage":"Welche Pflichten gelten im Taxigewerbe wegen der Schwarzarbeitsbekämpfung? Wähle alle richtigen.","optionen":["Fahrer müssen Personalausweis, Pass oder Ersatzpapier mitführen.","Beginn, Ende und Dauer der Arbeitszeit spätestens am 7. Tag aufzeichnen.","Die Aufzeichnungen mindestens 2 Jahre aufbewahren.","Jeden Fahrer wöchentlich beim Zoll anmelden.","Den Fahrer nur bar bezahlen."],"richtig":[0,1,2],"erklaerung":"Das Personenbeförderungsgewerbe steht in § 2a SchwarzArbG. Daraus folgen Ausweispflicht und die Aufzeichnungspflicht nach § 17 MiLoG.","quelle":"§ 2a SchwarzArbG, § 17 MiLoG","lc":true,"lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-04","typ":"zahl","frage":"Eine Fahrerin arbeitet an 4 Tagen pro Woche. Wie viele Tage gesetzlichen Mindesturlaub hat sie im Jahr?","richtig":16,"einheit":"Tage","tol":0,"dez":0,"loesung":"24 Werktage ÷ 6 × 4 Arbeitstage = 16 Urlaubstage","erklaerung":"Der gesetzliche Urlaub beträgt 24 Werktage bei einer 6-Tage-Woche. Bei weniger Arbeitstagen rechnet man anteilig um.","quelle":"§ 3 BUrlG","lc":true,"lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-05","typ":"single","frage":"Wie lange zahlt der Arbeitgeber den Lohn bei Krankheit weiter?","optionen":["3 Tage","2 Wochen","6 Wochen","6 Monate"],"fest":true,"richtig":2,"erklaerung":"Bis zu 6 Wochen, danach Krankengeld der Krankenkasse. Voraussetzung: 4 Wochen ununterbrochene Beschäftigung.","quelle":"§ 3 EFZG","lc":true,"lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-06","typ":"single","frage":"Wie muss eine Kündigung erfolgen, damit sie wirksam ist?","optionen":["Mündlich reicht, wenn ein Zeuge dabei ist.","Schriftlich mit eigenhändiger Unterschrift; E-Mail oder SMS reichen nicht.","Per E-Mail mit Lesebestätigung","Per WhatsApp, wenn der Empfänger den Haken sieht"],"richtig":1,"erklaerung":"Die Beendigung durch Kündigung bedarf der Schriftform; die elektronische Form ist ausgeschlossen.","quelle":"§ 623 BGB","lc":true,"lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-07","typ":"single","frage":"Welche Kündigungsfrist gilt in der Probezeit?","optionen":["1 Woche","2 Wochen","4 Wochen zum 15. oder Monatsende","1 Monat"],"richtig":1,"erklaerung":"Während einer vereinbarten Probezeit von höchstens 6 Monaten kann mit einer Frist von 2 Wochen gekündigt werden.","quelle":"§ 622 Abs. 3 BGB","lc":true,"lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-08","typ":"single","frage":"Was ist die gesetzliche Grundkündigungsfrist?","optionen":["2 Wochen zum Monatsende","4 Wochen zum 15. oder zum Ende eines Kalendermonats","3 Monate zum Quartalsende","6 Wochen zum Quartalsende"],"richtig":1,"erklaerung":"Die Grundfrist gilt für Arbeitnehmer und Arbeitgeber. Bei längerer Betriebszugehörigkeit verlängert sie sich für Kündigungen durch den Arbeitgeber.","quelle":"§ 622 Abs. 1 BGB","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-09","typ":"single","frage":"Ein Fahrer ist seit 8 Jahren im Betrieb. Der Arbeitgeber kündigt ordentlich. Welche Frist gilt mindestens?","optionen":["4 Wochen zum 15. oder Monatsende","1 Monat zum Monatsende","3 Monate zum Ende eines Kalendermonats","7 Monate zum Monatsende"],"richtig":2,"erklaerung":"Nach 8 Jahren Betriebszugehörigkeit: 3 Monate zum Ende eines Kalendermonats.","quelle":"§ 622 Abs. 2 BGB","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-10","typ":"multi","frage":"Was gilt für eine Befristung ohne sachlichen Grund? Wähle alle richtigen.","optionen":["Höchstdauer 2 Jahre","Höchstens 3 Verlängerungen innerhalb dieser Zeit","Muss schriftlich vor Arbeitsbeginn vereinbart werden","Unbegrenzt oft verlängerbar","Mündlich reicht"],"richtig":[0,1,2],"erklaerung":"Ohne Schriftform gilt der Vertrag als unbefristet.","quelle":"§§ 14, 16 TzBfG","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-11","typ":"single","frage":"Wann gilt das Kündigungsschutzgesetz?","optionen":["In jedem Betrieb ab dem ersten Tag","Bei mehr als 10 Arbeitnehmern im Betrieb und einem Arbeitsverhältnis von mehr als 6 Monaten","Nur für Beamte","Nur bei Betrieben mit Betriebsrat"],"richtig":1,"erklaerung":"Schwellenwert: mehr als 10 Arbeitnehmer (§ 23 KSchG), Wartezeit: mehr als 6 Monate (§ 1 KSchG).","quelle":"§§ 1, 23 KSchG","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-12","typ":"single","frage":"Innerhalb welcher Frist muss eine fristlose Kündigung nach Kenntnis des Grundes ausgesprochen werden?","optionen":["3 Tage","2 Wochen","1 Monat","3 Monate"],"fest":true,"richtig":1,"erklaerung":"Die Kündigung aus wichtigem Grund kann nur innerhalb von zwei Wochen ab Kenntnis der maßgebenden Tatsachen erfolgen.","quelle":"§ 626 Abs. 2 BGB","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-13","typ":"tf","frage":"Für Minijobber gilt der Mindestlohn nicht.","richtig":false,"erklaerung":"Der Mindestlohn gilt auch für geringfügig Beschäftigte. Außerdem gilt für sie die Aufzeichnungspflicht nach § 17 MiLoG.","quelle":"MiLoG","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-14","typ":"single","frage":"Wie hoch ist die Minijob-Grenze im Jahr 2026?","optionen":["520 €","556 €","603 €","700 €"],"fest":true,"richtig":2,"erklaerung":"Die Grenze wird aus dem Mindestlohn berechnet: 13,90 € × 130 ÷ 3 = 602,33 €, aufgerundet 603 €.","quelle":"§ 8 Abs. 1a SGB IV","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-15","typ":"single","frage":"Wie lange sind Schutzfristen nach dem Mutterschutzgesetz?","optionen":["2 Wochen vor und 4 Wochen nach der Geburt","6 Wochen vor und 8 Wochen nach der Geburt","3 Monate vor und 3 Monate nach der Geburt","Nur 8 Wochen nach der Geburt"],"richtig":1,"erklaerung":"6 Wochen vor und 8 Wochen nach der Entbindung (bei Früh- und Mehrlingsgeburten länger).","quelle":"§ 3 MuSchG","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-16","typ":"tf","frage":"Wer sich gegen eine Kündigung wehren will, muss innerhalb von 3 Wochen nach Zugang Klage beim Arbeitsgericht erheben.","richtig":true,"erklaerung":"Klagefrist nach § 4 KSchG.","quelle":"§ 4 KSchG","lek":"arbeitsrecht","sg":"1.4"},{"id":"ar-17","typ":"offen","frage":"Ein Taxiunternehmer stellt einen Fahrer auf Minijob-Basis ein. Welche arbeitsrechtlichen Pflichten hat er? Nennen Sie mindestens vier.","muster":"<ul><li>Mindestlohn zahlen (13,90 € ab 2026), Verdienst bis 603 € im Monat</li><li>Arbeitszeit (Beginn, Ende, Dauer) bis zum 7. Tag aufzeichnen und 2 Jahre aufbewahren (§ 17 MiLoG)</li><li>Wesentliche Arbeitsbedingungen schriftlich nachweisen (NachwG), im Taxigewerbe mit Unterschrift</li><li>Urlaub anteilig gewähren (BUrlG), Lohnfortzahlung bei Krankheit (EFZG)</li><li>Sofortmeldung und Anmeldung bei der Minijob-Zentrale</li><li>Fahrer auf Ausweispflicht hinweisen (§ 2a SchwarzArbG), P-Schein prüfen</li></ul>","punkte_liste":[{"t":"Mindestlohn / Minijob-Grenze","p":1},{"t":"Arbeitszeit aufzeichnen (7 Tage, 2 Jahre)","p":1},{"t":"Schriftlicher Nachweis der Arbeitsbedingungen","p":1},{"t":"Urlaub und/oder Lohnfortzahlung","p":1},{"t":"Weitere Pflicht (Anmeldung Minijob-Zentrale/Sofortmeldung, Ausweis, P-Schein)","p":1}],"quelle":"MiLoG, NachwG, BUrlG, EFZG, SchwarzArbG","lek":"arbeitsrecht","sg":"1.4"},{"id":"az-01","typ":"single","frage":"Ein angestellter Taxifahrer arbeitet 9 Stunden und 30 Minuten. Wie lang muss seine Pause mindestens sein?","optionen":["15 Minuten","30 Minuten","45 Minuten","60 Minuten"],"fest":true,"richtig":2,"erklaerung":"Bei mehr als 9 Stunden Arbeitszeit mindestens 45 Minuten. Bei mehr als 6 bis 9 Stunden 30 Minuten.","quelle":"§ 4 ArbZG","lc":true,"lek":"arbeitszeit","sg":"1.4"},{"id":"az-02","typ":"single","frage":"Ein Fahrer beendet seine Schicht um 2:00 Uhr. Wann darf er frühestens wieder anfangen, wenn keine Verkürzung genutzt wird?","optionen":["8:00 Uhr","11:00 Uhr","13:00 Uhr","14:00 Uhr"],"fest":true,"richtig":2,"erklaerung":"Ununterbrochene Ruhezeit von mindestens 11 Stunden: 2:00 + 11 h = 13:00 Uhr. Im Verkehrsbetrieb wäre mit Ausgleich auch 12:00 Uhr möglich.","quelle":"§ 5 ArbZG","lc":true,"lek":"arbeitszeit","sg":"1.4"},{"id":"az-03","typ":"multi","frage":"Was gilt für Sonntagsarbeit von angestellten Taxifahrern? Wähle alle richtigen.","optionen":["Sie ist in Verkehrsbetrieben grundsätzlich erlaubt.","Mindestens 15 Sonntage im Jahr müssen frei bleiben.","Für einen Arbeitssonntag gibt es einen Ersatzruhetag innerhalb von 2 Wochen.","Sonntagsarbeit ist für Taxifahrer verboten.","Für Sonntagsarbeit gibt es nie einen Ausgleich."],"richtig":[0,1,2],"erklaerung":"§ 10 Abs. 1 Nr. 10 ArbZG erlaubt Sonntagsarbeit in Verkehrsbetrieben; § 11 regelt den Ausgleich.","quelle":"§§ 10, 11 ArbZG","lc":true,"lek":"arbeitszeit","sg":"1.4"},{"id":"az-04","typ":"tf","frage":"Taxis müssen einen Fahrtenschreiber haben, weil für sie die EU-Lenk- und Ruhezeiten (VO 561/2006) gelten.","richtig":false,"erklaerung":"Die VO 561/2006 gilt im Personenverkehr nur für Fahrzeuge für mehr als 9 Personen einschließlich Fahrer. Taxis und Mietwagen fallen nicht darunter. Für angestellte Fahrer gilt das ArbZG.","quelle":"Art. 2 VO (EG) 561/2006","lc":true,"lek":"arbeitszeit","sg":"1.4"},{"id":"az-05","typ":"single","frage":"Wie lange darf ein Arbeitnehmer an einem Werktag höchstens arbeiten?","optionen":["8 Stunden, ohne Ausnahme","10 Stunden, wenn im Durchschnitt von 6 Monaten oder 24 Wochen 8 Stunden pro Werktag nicht überschritten werden","12 Stunden","Unbegrenzt, wenn er zustimmt"],"richtig":1,"erklaerung":"Regel 8 Stunden; Verlängerung auf 10 Stunden mit Ausgleich.","quelle":"§ 3 ArbZG","lek":"arbeitszeit","sg":"1.4"},{"id":"az-06","typ":"single","frage":"Um wie viel darf die Ruhezeit in Verkehrsbetrieben verkürzt werden, und wie wird ausgeglichen?","optionen":["Um 3 Stunden, kein Ausgleich nötig","Um 1 Stunde; Ausgleich durch eine andere Ruhezeit von mindestens 12 Stunden innerhalb eines Kalendermonats oder 4 Wochen","Um 2 Stunden; Ausgleich innerhalb eines Jahres","Gar nicht"],"richtig":1,"erklaerung":"§ 5 Abs. 2 ArbZG nennt ausdrücklich Verkehrsbetriebe.","quelle":"§ 5 Abs. 2 ArbZG","lek":"arbeitszeit","sg":"1.4"},{"id":"az-07","typ":"tf","frage":"Das Arbeitszeitgesetz gilt auch für den selbständigen Taxiunternehmer, der selbst fährt.","richtig":false,"erklaerung":"Das ArbZG gilt für Arbeitnehmer. Selbständige fallen nicht darunter.","quelle":"§ 2 Abs. 2 ArbZG","lek":"arbeitszeit","sg":"1.4"},{"id":"az-08","typ":"single","frage":"Welcher Zeitraum ist nach dem ArbZG die Nachtzeit?","optionen":["20 bis 4 Uhr","22 bis 5 Uhr","23 bis 6 Uhr","0 bis 6 Uhr"],"fest":true,"richtig":2,"erklaerung":"Nachtzeit ist die Zeit von 23 bis 6 Uhr. Nachtarbeit ist Arbeit, die mehr als 2 Stunden der Nachtzeit umfasst.","quelle":"§ 2 Abs. 3 und 4 ArbZG","lek":"arbeitszeit","sg":"1.4"},{"id":"az-09","typ":"tf","frage":"Wartezeit am Taxistand, in der der Fahrer jederzeit losfahren muss, zählt als Pause.","richtig":false,"erklaerung":"Eine Pause ist eine im Voraus feststehende Unterbrechung, in der der Arbeitnehmer frei ist. Bereitschaft am Stand ist Arbeitszeit.","quelle":"§ 4 ArbZG","lek":"arbeitszeit","sg":"1.4"},{"id":"az-10","typ":"zahl","frage":"Ein Fahrer beginnt um 16:00 Uhr und hört um 2:15 Uhr auf. Er macht 45 Minuten Pause. Wie lang ist seine Arbeitszeit in Stunden? (z. B. 8,5)","richtig":9.5,"einheit":"h","tol":0.01,"loesung":"16:00 bis 2:15 = 10 h 15 min\n10 h 15 min − 45 min Pause = 9 h 30 min = 9,5 h","erklaerung":"Arbeitszeit = Zeit von Beginn bis Ende ohne Pausen. 9,5 h liegt über 8 h: nur mit Ausgleich erlaubt, und die Pause von 45 min ist nötig.","quelle":"§§ 2–4 ArbZG","lek":"arbeitszeit","sg":"1.4"},{"id":"az-11","typ":"offen","frage":"Erläutern Sie die Regeln des Arbeitszeitgesetzes zu Höchstarbeitszeit, Pausen und Ruhezeit für angestellte Taxifahrer.","muster":"<p>Höchstarbeitszeit: 8 Stunden pro Werktag, bis zu 10 Stunden, wenn innerhalb von 6 Monaten oder 24 Wochen im Durchschnitt 8 Stunden nicht überschritten werden (§ 3). Pausen: mehr als 6 Stunden mindestens 30 Minuten, mehr als 9 Stunden 45 Minuten, in Abschnitten von mindestens 15 Minuten; nicht länger als 6 Stunden ohne Pause (§ 4). Ruhezeit: mindestens 11 Stunden ununterbrochen; in Verkehrsbetrieben Verkürzung um 1 Stunde möglich, Ausgleich auf 12 Stunden innerhalb eines Monats oder 4 Wochen (§ 5).</p>","punkte_liste":[{"t":"8 Stunden, bis 10 Stunden mit Ausgleich (6 Monate/24 Wochen)","p":1},{"t":"Pausen 30 min (> 6 h) / 45 min (> 9 h)","p":1},{"t":"Pausenabschnitte 15 min, max. 6 h ohne Pause","p":1},{"t":"Ruhezeit 11 h","p":1},{"t":"Verkehrsbetrieb: Verkürzung um 1 h, Ausgleich auf 12 h","p":1}],"quelle":"§§ 3–5 ArbZG","lek":"arbeitszeit","sg":"1.4"},{"id":"au-01","typ":"zuordnung","frage":"Was gilt für wen?","kategorien":["nur Taxi","nur Mietwagen","beide"],"paare":[{"t":"Alarmanlage, vom Fahrersitz auslösbar","k":2,"w":"§ 25 Abs. 2 BOKraft gilt für Taxen und Mietwagen."},{"t":"Navigationsgerät mit Echtzeit-Verkehrsdaten","k":0,"w":"§ 28a BOKraft: Taxen."},{"t":"Wegstreckenzähler","k":1,"w":"§ 30 BOKraft."},{"t":"Mindestens 2 Türen auf der rechten Seite","k":2,"w":"§ 25 Abs. 1 BOKraft."},{"t":"Platz für mindestens 50 kg Gepäck bei voller Besetzung","k":0,"w":"§ 29 BOKraft."},{"t":"Ordnungsnummer an der Heckscheibe","k":2,"w":"§ 27 BOKraft."}],"erklaerung":"Für Mietwagen gelten §§ 25, 27, 30 BOKraft (§ 31).","quelle":"BOKraft","lc":true,"lek":"ausruestung","sg":"3.3"},{"id":"au-02","typ":"single","frage":"Was muss die Alarmanlage in einem Taxi können?","optionen":["Nur die Polizei anrufen","Vom Fahrersitz auslösbar: Hupe ertönt im Intervall, Scheinwerfer und hintere Blinker blinken","Nur das Taxischild rot leuchten lassen","Die Türen verriegeln"],"richtig":1,"erklaerung":"§ 25 Abs. 2 BOKraft. Das Taxischild darf zusätzlich blinken, das ist aber nicht Pflicht.","quelle":"§ 25 BOKraft","lc":true,"lek":"ausruestung","sg":"3.3"},{"id":"au-03","typ":"single","frage":"Wie tief muss das Reifenprofil gesetzlich mindestens sein?","optionen":["1,0 mm","1,6 mm","3,0 mm","4,0 mm"],"fest":true,"richtig":1,"erklaerung":"1,6 mm nach § 36 StVZO. Empfohlen werden 3 mm (Sommer) bzw. 4 mm (Winter).","quelle":"§ 36 Abs. 2 StVZO","lc":true,"lek":"ausruestung","sg":"3.3"},{"id":"au-04","typ":"tf","frage":"Eine Trennwand zwischen Fahrer und Fahrgästen ist in Taxis vorgeschrieben.","richtig":false,"erklaerung":"Eine Trennwand ist erlaubt. Wenn eingebaut, muss sie ausreichend schusshemmend sein.","quelle":"§ 25 Abs. 3 BOKraft","lek":"ausruestung","sg":"3.3"},{"id":"au-05","typ":"multi","frage":"Was gehört zur Pflichtausrüstung jedes Pkw? Wähle alle richtigen.","optionen":["Verbandkasten","Warndreieck","Warnweste","Feuerlöscher","Abschleppseil"],"richtig":[0,1,2],"erklaerung":"Feuerlöscher sind für Busse Pflicht. Ein Abschleppseil verlangt § 18 BOKraft nur, wenn die Umstände es erfordern.","quelle":"§§ 35h, 53a StVZO","lek":"ausruestung","sg":"3.3"},{"id":"au-06","typ":"tf","frage":"Seit Oktober 2024 gelten nur noch Reifen mit Alpine-Symbol als wintertauglich.","richtig":true,"erklaerung":"Die Übergangsfrist für reine M+S-Reifen ist am 30.9.2024 abgelaufen.","quelle":"§ 36 Abs. 4 StVZO, § 2 Abs. 3a StVO","lek":"ausruestung","sg":"3.3"},{"id":"au-07","typ":"single","frage":"Ein Fahrzeug hat Genehmigungen als Taxi und als Mietwagen. Es fährt gerade einen Mietwagenauftrag. Was gilt für das Taxischild?","optionen":["Es muss leuchten.","Es darf nicht benutzt werden.","Es muss rot blinken.","Egal"],"richtig":1,"erklaerung":"Bei Verwendung im Mietwagenverkehr darf das Taxischild nicht verwendet werden (§ 31 BOKraft).","quelle":"§ 31 BOKraft","lek":"ausruestung","sg":"3.3"},{"id":"au-08","typ":"offen","frage":"Nennen Sie sechs Ausrüstungsmerkmale, die ein Taxi nach der BOKraft haben muss.","muster":"<ul><li>Mindestens 2 Türen rechts (§ 25)</li><li>Alarmanlage (§ 25)</li><li>Hell-elfenbein RAL 1015 (§ 26)</li><li>Beleuchtetes Taxischild (§ 26)</li><li>Ordnungsnummer und Unternehmeranschrift (§ 27)</li><li>Geeichter Fahrpreisanzeiger (§ 28)</li><li>Navigationsgerät mit Echtzeitdaten (§ 28a)</li><li>50 kg Gepäck bei voller Besetzung (§ 29)</li></ul>","punkte_liste":[{"t":"Zwei richtige Merkmale","p":1},{"t":"Vier richtige Merkmale","p":1},{"t":"Sechs richtige Merkmale","p":1}],"quelle":"§§ 25–29 BOKraft","lek":"ausruestung","sg":"3.3"},{"id":"bf-01","typ":"single","frage":"Ab welchen Grenzen ist ein Gewerbetreibender nach § 141 AO zur Buchführung verpflichtet?","optionen":["Umsatz über 100.000 € oder Gewinn über 25.000 €","Umsatz über 800.000 € oder Gewinn über 80.000 €","Ab 2 Fahrzeugen","Ab dem ersten Angestellten"],"richtig":1,"erklaerung":"Seit 2024 gelten 800.000 € Umsatz oder 80.000 € Gewinn. Kaufleute nach HGB sind unabhängig davon buchführungspflichtig (Einzelkaufleute unter diesen Grenzen können befreit sein).","quelle":"§ 141 AO","lc":true,"lek":"buchfuehrung","sg":"2.5"},{"id":"bf-02","typ":"zuordnung","frage":"Wie lange musst du aufbewahren?","kategorien":["6 Jahre","8 Jahre","10 Jahre"],"paare":[{"t":"Tankquittung","k":1,"w":"Buchungsbeleg: 8 Jahre (seit 2025)."},{"t":"Jahresabschluss / Bilanz","k":2,"w":"Bücher und Abschlüsse: 10 Jahre."},{"t":"Kassenbuch","k":2,"w":"Bücher und Aufzeichnungen: 10 Jahre."},{"t":"E-Mail mit einem Angebot an einen Firmenkunden","k":0,"w":"Geschäftsbrief: 6 Jahre."},{"t":"Werkstattrechnung","k":1,"w":"Buchungsbeleg: 8 Jahre."}],"erklaerung":"Die Frist beginnt jeweils am Ende des Kalenderjahres.","quelle":"§ 147 AO","lc":true,"lek":"buchfuehrung","sg":"2.5"},{"id":"bf-03","typ":"zahl","frage":"Im Kassenbuch der Lektion steht am Ende des 01.03. ein Bestand von 133,90 €. Am 02.03. kommen 268,10 € Bareinnahmen dazu. Wie hoch ist der neue Kassenbestand?","richtig":402,"einheit":"€","tol":0.005,"loesung":"133,90 € + 268,10 € = 402,00 €","erklaerung":"Bestand + Einnahmen − Ausgaben.","quelle":"Kassenbuch","lc":true,"lek":"buchfuehrung","sg":"2.5"},{"id":"bf-04","typ":"multi","frage":"Was gilt für ein ordnungsgemäßes Kassenbuch? Wähle alle richtigen.","optionen":["Täglich und zeitnah führen","Der Kassenbestand darf nie negativ sein","Der gezählte Bestand muss mit dem Buch übereinstimmen (Kassensturzfähigkeit)","Am Monatsende reicht eine Summe aller Einnahmen","Änderungen mit Tipp-Ex sind erlaubt, wenn sie ordentlich aussehen"],"richtig":[0,1,2],"erklaerung":"Bargeschäfte sind einzeln und täglich aufzuzeichnen. Änderungen müssen erkennbar bleiben.","quelle":"§ 146 AO, GoBD","lc":true,"lek":"buchfuehrung","sg":"2.5"},{"id":"bf-05","typ":"single","frage":"Ein Taxiunternehmer schickt im Dezember 2026 eine Sammelrechnung an eine Krankenkasse. Sie zahlt am 20. Januar 2027. Wann ist das bei der EÜR eine Betriebseinnahme?","optionen":["2026, weil die Fahrten 2026 waren","2027, weil das Geld 2027 zufließt","Je zur Hälfte","Gar nicht"],"richtig":1,"erklaerung":"Zuflussprinzip nach § 11 EStG. Die 10-Tage-Regel gilt nur für regelmäßig wiederkehrende Einnahmen und nur bis 10. Januar.","quelle":"§ 11 EStG","lc":true,"lek":"buchfuehrung","sg":"2.5"},{"id":"bf-06","typ":"zahl","frage":"Ein Taxi für 40.000 € netto wird am 1. Juli angeschafft. Nutzungsdauer laut AfA-Tabelle: 5 Jahre. Wie hoch ist die AfA im Anschaffungsjahr?","richtig":4000,"einheit":"€","tol":0.5,"loesung":"40.000 € ÷ 5 = 8.000 € pro Jahr\nJuli bis Dezember = 6 Monate\n8.000 € × 6/12 = 4.000 €","erklaerung":"Im Anschaffungsjahr zeitanteilig nach vollen Monaten. Steuerlich ohne Restwert.","quelle":"§ 7 EStG","lc":true,"lek":"buchfuehrung","sg":"2.5"},{"id":"bf-07","typ":"single","frage":"Welcher Buchungssatz ist richtig? Der Unternehmer bringt 600 € Bargeld aus der Kasse zur Bank.","optionen":["Kasse an Bank 600 €","Bank an Kasse 600 €","Erlöse an Kasse 600 €","Privat an Bank 600 €"],"richtig":1,"erklaerung":"Das Bankkonto nimmt zu (Soll), die Kasse nimmt ab (Haben): Bank an Kasse.","quelle":"Buchungssatz","lc":true,"lek":"buchfuehrung","sg":"2.5"},{"id":"bf-08","typ":"single","frage":"Was ist ein geringwertiges Wirtschaftsgut, das sofort abgeschrieben werden darf?","optionen":["Alles unter 5.000 €","Ein selbständig nutzbares Wirtschaftsgut bis 800 € netto, z. B. ein Kartenterminal","Jedes gebrauchte Fahrzeug","Nur Büromaterial"],"richtig":1,"erklaerung":"§ 6 Abs. 2 EStG: bis 800 € netto Sofortabzug.","quelle":"§ 6 Abs. 2 EStG","lek":"buchfuehrung","sg":"2.5"},{"id":"bf-09","typ":"single","frage":"Was ist der Unterschied zwischen Inventur und Inventar?","optionen":["Es gibt keinen Unterschied.","Inventur ist die Bestandsaufnahme (Tätigkeit), Inventar das Verzeichnis als Ergebnis.","Inventar ist die Tätigkeit, Inventur das Ergebnis.","Inventur betrifft nur Fahrzeuge."],"richtig":1,"erklaerung":"Inventur = zählen, messen, bewerten. Inventar = ausführliches Verzeichnis von Vermögen und Schulden.","quelle":"§ 240 HGB","lek":"buchfuehrung","sg":"2.5"},{"id":"bf-10","typ":"tf","frage":"In der Einnahmen-Überschuss-Rechnung wird der kalkulatorische Unternehmerlohn als Betriebsausgabe abgezogen.","richtig":false,"erklaerung":"Kalkulatorische Kosten (Unternehmerlohn, kalkulatorische Zinsen) gibt es nur in der Kostenrechnung. In der EÜR ist der Gewinn das Einkommen des Unternehmers.","quelle":"§ 4 Abs. 3 EStG","lek":"buchfuehrung","sg":"2.5"},{"id":"bf-11","typ":"single","frage":"Eine Quittung stammt vom 15. Mai 2026. Ab wann darf sie frühestens vernichtet werden?","optionen":["15. Mai 2034","1. Januar 2035","1. Januar 2037","15. Mai 2036"],"richtig":1,"erklaerung":"Buchungsbeleg: 8 Jahre ab Ende des Kalenderjahres 2026 → Ende 2034 → ab 1. Januar 2035.","quelle":"§ 147 Abs. 3 und 4 AO","lek":"buchfuehrung","sg":"2.5"},{"id":"bf-12","typ":"offen","frage":"Nennen Sie die Anforderungen an eine ordnungsgemäße Kassenführung im Taxibetrieb.","muster":"<ul><li>Jede Bareinnahme einzeln aufzeichnen (Einzelaufzeichnungspflicht, Taxameter mit TSE)</li><li>Kassenbuch täglich und zeitnah, chronologisch, mit Belegen</li><li>Kein negativer Kassenbestand, Kassensturzfähigkeit</li><li>Keine unerkennbaren Änderungen (GoBD), unveränderbare Software</li><li>Privatentnahmen/-einlagen und Bankeinzahlungen erfassen</li><li>Schichtzettel bzw. Taxameterdaten aufbewahren; Aufbewahrungsfristen (10/8 Jahre)</li><li>Belegausgabe an den Fahrgast</li></ul>","punkte_liste":[{"t":"Einzelaufzeichnung / Taxameter mit TSE","p":1},{"t":"täglich, zeitnah, chronologisch, mit Belegen","p":1},{"t":"kein negativer Bestand / kassensturzfähig","p":1},{"t":"Unveränderbarkeit (GoBD) oder Aufbewahrungsfristen","p":1}],"quelle":"§§ 146, 146a, 147 AO, GoBD","lek":"buchfuehrung","sg":"2.5"},{"id":"da-01","typ":"multi","frage":"Welche Dokumente sollte ein Taxifahrer bei einer Fahrt von Aachen nach Lüttich dabeihaben? Wähle alle richtigen.","optionen":["Personalausweis oder Reisepass","Führerschein und P-Schein","Zulassungsbescheinigung Teil I","Genehmigung oder gekürzte amtliche Ausfertigung","Zulassungsbescheinigung Teil II"],"richtig":[0,1,2,3],"erklaerung":"Teil II (Fahrzeugbrief) gehört nie ins Fahrzeug.","quelle":"PBefG, FeV, FZV","lc":true,"lek":"dokumente-ausland","sg":"5.3"},{"id":"da-02","typ":"single","frage":"Wofür ist die Internationale Versicherungskarte („Grüne Karte“) gut?","optionen":["Sie ersetzt den Führerschein im Ausland.","Sie weist die Kfz-Haftpflichtversicherung nach; in der EU nicht zwingend, aber hilfreich, außerhalb der EU teils Pflicht.","Sie ist die Genehmigung für Auslandsfahrten.","Sie berechtigt zur Kabotage."],"richtig":1,"erklaerung":"Innerhalb der EU gilt das Kennzeichen als Versicherungsnachweis.","quelle":"Versicherungsrecht","lc":true,"lek":"dokumente-ausland","sg":"5.3"},{"id":"da-03","typ":"tf","frage":"Der Europäische Unfallbericht ist ein einheitliches Formular, das die Schadenmeldung nach einem Unfall im Ausland erleichtert.","richtig":true,"erklaerung":"Er ist in allen EU-Sprachen gleich aufgebaut.","quelle":"Versicherungswesen","lek":"dokumente-ausland","sg":"5.3"},{"id":"da-04","typ":"single","frage":"Warum ist bei einem Mietwagen im Ausland ein Auftragsnachweis sinnvoll?","optionen":["Für die Mautberechnung","Um zu zeigen, dass der Auftrag über den Betriebssitz kam und keine verbotene Kabotage vorliegt","Er ist ein Ersatz für den Fahrzeugschein","Für die Kfz-Steuer"],"richtig":1,"erklaerung":"So lässt sich bei Kontrollen belegen, dass die Fahrt legal ist.","quelle":"§ 49 Abs. 4 PBefG","lek":"dokumente-ausland","sg":"5.3"},{"id":"dk-01","typ":"zuordnung","frage":"Zu wem gehört das Dokument?","kategorien":["Fahrer","Fahrzeug","Unternehmen"],"paare":[{"t":"Fahrerlaubnis zur Fahrgastbeförderung","k":0,"w":"§ 48 Abs. 3 FeV."},{"t":"Zulassungsbescheinigung Teil I","k":1,"w":"Fahrzeugschein, auch digital in der i-Kfz-App."},{"t":"Gekürzte amtliche Ausfertigung der Genehmigung","k":2,"w":"§ 17 Abs. 4 PBefG."},{"t":"Personalausweis","k":0,"w":"§ 2a SchwarzArbG, Vorlage beim Zoll."},{"t":"Gültiger Taxitarif","k":2,"w":"§ 10 BOKraft: Vorschriften über Entgelte und Beförderungsbedingungen."}],"erklaerung":"Fahrer-, fahrzeug- und unternehmensbezogene Dokumente.","quelle":"PBefG, FeV, SchwarzArbG, BOKraft","lc":true,"lek":"dokumente","sg":"2.9"},{"id":"dk-02","typ":"single","frage":"Wo muss im Taxi die Ordnungsnummer angebracht sein?","optionen":["Auf dem Dach neben dem Taxischild","Unten rechts an der Heckscheibe, von innen und außen lesbar","Am Armaturenbrett","Auf der Fahrertür"],"richtig":1,"erklaerung":"§ 27 BOKraft. Zusätzlich im Taxi innen: Name und Betriebssitz des Unternehmers.","quelle":"§ 27 BOKraft","lc":true,"lek":"dokumente","sg":"2.9"},{"id":"dk-03","typ":"single","frage":"Wie lange müssen Auftragsaufzeichnungen im Mietwagenverkehr aufbewahrt werden?","optionen":["1 Jahr","2 Jahre","6 Jahre","10 Jahre"],"fest":true,"richtig":0,"erklaerung":"Nach § 49 Abs. 4 PBefG ein Jahr. Steuerliche Fristen können für dieselben Daten länger sein, wenn sie zugleich Buchungsbelege sind.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"dokumente","sg":"2.9"},{"id":"dk-04","typ":"multi","frage":"Welche Dokumente muss ein angestellter Taxifahrer bei jeder Fahrt dabeihaben? Wähle alle richtigen.","optionen":["Führerschein","P-Schein","Personalausweis oder Pass","Zulassungsbescheinigung Teil II (Fahrzeugbrief)","Seinen Arbeitsvertrag"],"richtig":[0,1,2],"erklaerung":"Der Fahrzeugbrief (Teil II) gehört nicht ins Auto. Ins Fahrzeug gehören außerdem Teil I, Genehmigungsausfertigung und Tarif.","quelle":"§ 48 FeV, § 2a SchwarzArbG","lek":"dokumente","sg":"2.9"},{"id":"dk-05","typ":"tf","frage":"Die Genehmigung nach § 17 PBefG darf im Fahrzeug auch elektronisch mitgeführt werden.","richtig":true,"erklaerung":"§ 17 Abs. 4 PBefG erlaubt schriftliche oder elektronische Form.","quelle":"§ 17 Abs. 4 PBefG","lek":"dokumente","sg":"2.9"},{"id":"dk-06","typ":"tf","frage":"Im Mietwagen muss innen ein Schild mit Name und Betriebssitz des Unternehmers angebracht sein.","richtig":false,"erklaerung":"Das Schild mit der Unternehmeranschrift schreibt § 27 BOKraft für Taxen vor. Mietwagen brauchen das Schild mit der Ordnungsnummer an der Heckscheibe.","quelle":"§ 27 BOKraft","lek":"dokumente","sg":"2.9"},{"id":"dk-07","typ":"offen","frage":"Bei einer Verkehrskontrolle fragt die Polizei nach den Papieren. Welche Dokumente muss ein Taxi bei jeder Fahrt mitführen? Ordnen Sie sie Fahrer, Fahrzeug und Unternehmen zu.","muster":"<p>Fahrer: Führerschein, Fahrerlaubnis zur Fahrgastbeförderung, Personalausweis/Pass. Fahrzeug: Zulassungsbescheinigung Teil I (Papier oder i-Kfz-App). Unternehmen: Genehmigungsurkunde oder gekürzte amtliche Ausfertigung, geltender Taxitarif/Beförderungsbedingungen. Außerdem: Ordnungsnummer an der Heckscheibe und Unternehmeranschrift innen.</p>","punkte_liste":[{"t":"Führerschein und P-Schein","p":1},{"t":"Ausweis (SchwarzArbG)","p":1},{"t":"Zulassungsbescheinigung Teil I","p":1},{"t":"Genehmigung/Ausfertigung und Tarif","p":1}],"quelle":"PBefG, FeV, BOKraft, SchwarzArbG","lek":"dokumente","sg":"2.9"},{"id":"fp-01","typ":"multi","frage":"Welche Voraussetzungen gelten für die Fahrerlaubnis zur Fahrgastbeförderung (Taxi/Mietwagen)? Wähle alle richtigen.","optionen":["Mindestalter 21 Jahre","Fahrerlaubnis Klasse B seit mindestens 2 Jahren","Führungszeugnis und Auszug aus dem Fahreignungsregister","Ärztliches Zeugnis und Nachweis des Sehvermögens","Bestandene Fachkundeprüfung für Unternehmer bei der IHK","Deutsche Staatsangehörigkeit"],"richtig":[0,1,2,3],"erklaerung":"Die Unternehmer-Fachkundeprüfung ist keine Voraussetzung für den P-Schein. Die Staatsangehörigkeit spielt keine Rolle.","quelle":"§ 48 Abs. 4 FeV","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-02","typ":"single","frage":"Wie lange gilt eine Fahrerlaubnis zur Fahrgastbeförderung höchstens?","optionen":["1 Jahr","2 Jahre","5 Jahre","unbefristet"],"fest":true,"richtig":2,"erklaerung":"Sie wird für höchstens 5 Jahre erteilt und kann jeweils um bis zu 5 Jahre verlängert werden.","quelle":"§ 48 Abs. 5 FeV","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-03","typ":"tf","frage":"Als Halter darf der Unternehmer einen Fahrer ohne gültigen P-Schein Fahrgäste befördern lassen, wenn der Fahrer einen normalen Führerschein hat und die Verlängerung beantragt ist.","richtig":false,"erklaerung":"Der Halter darf die Fahrgastbeförderung nicht anordnen oder zulassen, wenn der Fahrer die erforderliche Erlaubnis nicht hat.","quelle":"§ 48 Abs. 7 FeV","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-04","typ":"single","frage":"Wie viele Kinder muss ein Taxi auf den Rücksitzen mindestens mit Kindersitz sichern können (wenn nicht regelmäßig Kinder befördert werden)?","optionen":["Kein Kind, Taxis sind ausgenommen","1 Kind beliebigen Gewichts","2 Kinder ab 9 kg, davon mindestens 1 mit 9 bis 18 kg","So viele Kinder, wie Sitze vorhanden sind"],"richtig":2,"erklaerung":"Für Taxis gilt eine Erleichterung: Die Pflicht ist auf 2 Kinder ab 9 kg auf den Rücksitzen beschränkt, mindestens eines mit 9 bis 18 kg muss gesichert werden können.","quelle":"§ 21 Abs. 1a StVO","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-05","typ":"tf","frage":"Ein Taxiunternehmer fährt jeden Tag 3 Kinder zur Schule. Für diese Fahrten gilt die Erleichterung für Taxis bei der Kindersicherung nicht.","richtig":true,"erklaerung":"Die Erleichterung gilt nicht, wenn eine regelmäßige Beförderung von Kindern stattfindet. Dann braucht jedes Kind eine passende Rückhalteeinrichtung.","quelle":"§ 21 Abs. 1a StVO","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-06","typ":"single","frage":"Darf ein Taxi eine Busspur (Zeichen 245) benutzen?","optionen":["Ja, immer","Nur wenn ein Zusatzzeichen das erlaubt, z. B. „Taxi frei“","Nur mit Fahrgast","Nur nachts"],"richtig":1,"erklaerung":"Bussonderfahrstreifen sind grundsätzlich Linienbussen vorbehalten. Taxis dürfen sie nur nutzen, wenn ein Zusatzzeichen das erlaubt.","quelle":"§ 41 StVO, Anlage 2 Zeichen 245","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-07","typ":"tf","frage":"Taxifahrer sind bei der Fahrgastbeförderung von der Gurtpflicht befreit.","richtig":false,"erklaerung":"Die frühere Ausnahme für Taxifahrer wurde gestrichen (§ 21a Abs. 1 Nr. 1 StVO ist weggefallen). Heute gilt die Gurtpflicht.","quelle":"§ 21a StVO","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-08","typ":"single","frage":"Was gilt für Alkohol bei Taxi- und Mietwagenfahrern im Dienst?","optionen":["Bis 0,5 Promille ist erlaubt.","Bis 0,3 Promille ist erlaubt.","Alkohol und andere berauschende Mittel sind im Dienst und in der Dienstbereitschaft verboten.","Nur Bier ist erlaubt."],"richtig":2,"erklaerung":"Die BOKraft verbietet dem Fahrpersonal den Genuss alkoholischer Getränke und anderer berauschender Mittel während des Dienstes und der Dienstbereitschaft.","quelle":"§ 8 Abs. 3 Nr. 1 und Abs. 5 BOKraft","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-09","typ":"single","frage":"Ab welchem Alter braucht man für die Verlängerung des P-Scheins zusätzlich einen Nachweis der Leistungsfähigkeit?","optionen":["50 Jahre","60 Jahre","65 Jahre","70 Jahre"],"fest":true,"richtig":1,"erklaerung":"Für eine Verlängerung über das 60. Lebensjahr hinaus sind zusätzliche Nachweise nach Anlage 5 Nr. 2 und 3 FeV nötig.","quelle":"§ 48 Abs. 6 FeV","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-10","typ":"tf","frage":"Ein Fahrer mit Busführerschein Klasse D braucht für das Taxifahren keinen zusätzlichen P-Schein.","richtig":true,"erklaerung":"§ 48 Abs. 2 Nr. 4 FeV: Keine Fahrerlaubnis zur Fahrgastbeförderung nötig für Fahrer mit Klasse D oder D1.","quelle":"§ 48 Abs. 2 FeV","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-11","typ":"tf","frage":"Fahrgäste dürfen im Taxi rauchen, wenn der Fahrer zustimmt.","richtig":false,"erklaerung":"In Verkehrsmitteln des öffentlichen Personenverkehrs, zu denen Fahrzeuge nach dem PBefG gehören, gilt ein gesetzliches Rauchverbot.","quelle":"§§ 1, 2 BNichtrSchG","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-12","typ":"single","frage":"Ein Kind ist 10 Jahre alt und 152 cm groß. Braucht es im Taxi einen Kindersitz?","optionen":["Ja, alle Kinder unter 12 brauchen einen Kindersitz.","Nein, die Pflicht gilt nur für Kinder unter 12 Jahren, die kleiner als 150 cm sind.","Ja, bis 14 Jahre","Nur auf dem Beifahrersitz"],"richtig":1,"erklaerung":"Beide Merkmale müssen zusammenkommen: unter 12 Jahre und kleiner als 150 cm.","quelle":"§ 21 Abs. 1a StVO","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"fp-13","typ":"offen","frage":"Ein neuer Fahrer möchte bei Ihnen als Taxifahrer anfangen. Was müssen Sie als Unternehmer prüfen, bevor er Fahrgäste befördern darf?","muster":"<p>Gültige Fahrerlaubnis Klasse B (seit mindestens 2 Jahren) und gültige Fahrerlaubnis zur Fahrgastbeförderung (P-Schein, Ablaufdatum prüfen). Der Halter darf die Beförderung ohne P-Schein nicht zulassen (§ 48 Abs. 7 FeV). Außerdem: Anmeldung zur Sozialversicherung vor Arbeitsbeginn (Sofortmeldung), Arbeitsvertrag/Nachweis der Arbeitsbedingungen, Einweisung in Fahrzeug, Taxameter, Kindersitze und Verhaltensregeln (kein Alkohol, Rauchverbot).</p>","punkte_liste":[{"t":"Gültiger Führerschein Klasse B (seit mind. 2 Jahren)","p":1},{"t":"Gültiger P-Schein, Ablaufdatum kontrollieren","p":1},{"t":"Hinweis: Halter darf Beförderung ohne P-Schein nicht zulassen","p":1},{"t":"Weitere sinnvolle Punkte (Sofortmeldung SV, Arbeitsvertrag, Einweisung)","p":1}],"quelle":"§ 48 FeV","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3"},{"id":"aus-01","typ":"single","frage":"Was versteht man im Taxiverkehr unter Kabotage?","optionen":["Eine Fahrt über mehr als 50 km","Die Beförderung von Fahrgästen innerhalb eines anderen Staates durch ein ausländisches Fahrzeug","Eine Leerfahrt zurück zum Betriebssitz","Eine Fahrt mit mehr als 4 Fahrgästen"],"richtig":1,"erklaerung":"Beispiel: Ein Aachener Taxi fährt Fahrgäste von Vaals nach Maastricht. Das ist verboten.","quelle":"Grenzüberschreitender Verkehr","lc":true,"lek":"fahrten-ins-ausland","sg":"5.1"},{"id":"aus-02","typ":"zuordnung","frage":"Darf ein Aachener Taxi diese Fahrt machen?","kategorien":["erlaubt","verboten"],"paare":[{"t":"Aachen → Heerlen, Fahrgast steigt in Aachen ein","k":0,"w":"Fahrgäste ins Ausland bringen ist erlaubt."},{"t":"Heerlen → Kerkrade (beide NL)","k":1,"w":"Kabotage."},{"t":"Maastricht → Aachen, vorher telefonisch bestellt","k":0,"w":"Nach niederländischem Recht mit Vorbestellung erlaubt."},{"t":"Am Bahnhof Maastricht auf Fahrgäste warten","k":1,"w":"Bereithalten im Ausland ist nicht erlaubt."},{"t":"Eupen → Lüttich (beide BE)","k":1,"w":"Kabotage."}],"erklaerung":"Grundregel: hinbringen ja, innerhalb des anderen Landes nein.","quelle":"§ 52 PBefG, Recht NL/BE","lc":true,"lek":"fahrten-ins-ausland","sg":"5.1"},{"id":"aus-03","typ":"tf","frage":"Für eine Taxifahrt von Aachen nach Maastricht gilt automatisch der Aachener Taxitarif für die ganze Strecke.","richtig":false,"erklaerung":"Der Tarif gilt im Pflichtfahrbereich. Für Fahrten darüber hinaus wird der Preis nach der örtlichen Regel vereinbart, am besten vor Fahrtantritt.","quelle":"§§ 47, 51 PBefG","lc":true,"lek":"fahrten-ins-ausland","sg":"5.1"},{"id":"aus-04","typ":"single","frage":"Welches Recht gilt für ein niederländisches Taxi auf der deutschen Strecke einer Fahrt nach Aachen?","optionen":["Nur niederländisches Recht","Das deutsche PBefG und seine Verordnungen","EU-Busverordnung","Kein Recht"],"richtig":1,"erklaerung":"§ 52 Abs. 1 PBefG: Für grenzüberschreitenden Verkehr gilt das PBefG auch für Unternehmer mit Sitz im Ausland.","quelle":"§ 52 PBefG","lek":"fahrten-ins-ausland","sg":"5.1"},{"id":"aus-05","typ":"tf","frage":"Ein Mietwagen aus Aachen bringt einen Fahrgast nach Lüttich. Ohne neuen Auftrag über den Betriebssitz muss er zurück nach Aachen.","richtig":true,"erklaerung":"Die Rückkehrpflicht gilt auch nach Auslandsfahrten. Kabotage in Belgien wäre zudem verboten.","quelle":"§ 49 Abs. 4 PBefG","lek":"fahrten-ins-ausland","sg":"5.1"},{"id":"aus-06","typ":"offen","frage":"Ein Fahrgast steigt in Aachen ein und will nach Maastricht. Dort möchte er, dass das Taxi wartet und ihn danach zu einem Hotel in Valkenburg (NL) bringt. Wie beurteilen Sie das?","muster":"<p>Aachen → Maastricht: erlaubt (Beförderung ins Ausland), Preis vorher vereinbaren, da außerhalb des Pflichtfahrbereichs. Maastricht → Valkenburg: beide Orte in den Niederlanden, also Kabotage – für ein deutsches Taxi verboten (Bußgeld in NL, ca. 2.000 €). Lösung: Fahrgast direkt von Aachen nach Valkenburg bringen (eine durchgehende Fahrt aus Deutschland heraus) oder für die Strecke in den Niederlanden ein niederländisches Taxi nehmen.</p>","punkte_liste":[{"t":"Aachen → Maastricht erlaubt","p":1},{"t":"Maastricht → Valkenburg ist Kabotage, verboten","p":1},{"t":"Preis vorher vereinbaren / Tarif gilt nicht im Ausland","p":1},{"t":"Sinnvolle Alternative genannt","p":1}],"quelle":"§ 52 PBefG, Recht NL","lek":"fahrten-ins-ausland","sg":"5.1"},{"id":"fb-01","typ":"single","frage":"Was bedeutet das Verkehrszeichen 229 „Taxenstand“?","optionen":["Parkplatz für alle Fahrzeuge bis 30 Minuten","Wer ein Fahrzeug führt, darf dort nicht halten, ausgenommen für die Fahrgastbeförderung bereitgehaltene Taxen.","Nur Mietwagen dürfen dort warten.","Halten erlaubt zum Ein- und Aussteigen für alle"],"richtig":1,"erklaerung":"Auch Privatwagen dürfen am Taxenstand nicht halten.","quelle":"StVO Anlage 2, Zeichen 229","lc":true,"lek":"funk-bereitstellung","sg":"3.7"},{"id":"fb-02","typ":"tf","frage":"Ein Fahrgast am Taxenstand muss das erste Taxi in der Reihe nehmen.","richtig":false,"erklaerung":"Der Fahrgast hat nach den Taxenordnungen freie Wahl unter den bereitgehaltenen Taxis.","quelle":"Taxenordnung","lc":true,"lek":"funk-bereitstellung","sg":"3.7"},{"id":"fb-03","typ":"single","frage":"Wer teilt Frequenzen für ein eigenes Taxifunknetz zu?","optionen":["Die IHK","Die Genehmigungsbehörde","Die Bundesnetzagentur","Das Kraftfahrt-Bundesamt"],"richtig":2,"erklaerung":"Frequenzzuteilungen erteilt die Bundesnetzagentur nach dem Telekommunikationsgesetz.","quelle":"TKG","lc":true,"lek":"funk-bereitstellung","sg":"3.7"},{"id":"fb-04","typ":"single","frage":"Wo dürfen Taxen bereitgehalten werden?","optionen":["Überall, wo Parken erlaubt ist","An behördlich zugelassenen Stellen, grundsätzlich in der Gemeinde des Betriebssitzes","Nur am Betriebssitz","Nur an Bahnhöfen"],"richtig":1,"erklaerung":"§ 47 Abs. 1 und 2 PBefG.","quelle":"§ 47 PBefG","lek":"funk-bereitstellung","sg":"3.7"},{"id":"fb-05","typ":"tf","frage":"Wo genau sich Taxis am Stand aufstellen und wie sie nachrücken, regelt meist die örtliche Taxenordnung.","richtig":true,"erklaerung":"Die Ermächtigung dafür steht in § 47 Abs. 3 PBefG.","quelle":"§ 47 Abs. 3 PBefG","lek":"funk-bereitstellung","sg":"3.7"},{"id":"fb-06","typ":"single","frage":"Ein Taxifahrer stellt sein Taxi während seiner Mittagspause für eine Stunde am Taxenstand ab und geht essen. Ist das erlaubt?","optionen":["Ja, Taxis dürfen dort immer stehen.","Nein, am Taxenstand dürfen nur Taxen halten, die für die Fahrgastbeförderung bereitgehalten werden.","Ja, wenn das Taxischild aus ist.","Nur nachts"],"richtig":1,"erklaerung":"Ein Taxi in der Pause wird nicht bereitgehalten. Es blockiert den Stand für andere.","quelle":"Zeichen 229 StVO, Taxenordnung","lek":"funk-bereitstellung","sg":"3.7"},{"id":"gb-01","typ":"zahl","frage":"Ein Unternehmer will mit 4 Taxen beginnen. Wie viel Eigenkapital und Reserven muss er mindestens nachweisen?","richtig":6000,"einheit":"€","tol":1,"loesung":"1. Fahrzeug: 2.250 €\n3 weitere Fahrzeuge: 3 × 1.250 € = 3.750 €\nSumme: 6.000 €","erklaerung":"Für Taxi und Mietwagen gilt ein Viertel der EU-Beträge für Busse: 2.250 € für das erste und 1.250 € für jedes weitere Fahrzeug.","quelle":"§ 2 Abs. 1 Nr. 2 PBZugV, Art. 7 VO (EG) 1071/2009","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-02","typ":"single","frage":"Wie alt darf die Unbedenklichkeitsbescheinigung des Finanzamts bei Antragstellung höchstens sein?","optionen":["1 Monat","3 Monate","6 Monate","1 Jahr"],"fest":true,"richtig":1,"erklaerung":"Bescheinigungen von Finanzamt, Gemeinde, Sozialversicherung und Berufsgenossenschaft: höchstens 3 Monate. Die Eigenkapitalbescheinigung darf bis zu 1 Jahr alt sein.","quelle":"§ 2 Abs. 2 PBZugV","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-03","typ":"multi","frage":"Wie kann die fachliche Eignung für den Taxi- und Mietwagenverkehr nachgewiesen werden? Wähle alle richtigen.","optionen":["Bestandene Fachkundeprüfung bei der IHK","Eine von der Landesbehörde anerkannte gleichwertige Abschlussprüfung","Mindestens 3 Jahre leitende Tätigkeit in einem deutschen Taxi- oder Mietwagenunternehmen","Mindestens 5 Jahre Erfahrung als angestellter Taxifahrer","Ein Führerschein der Klasse B seit mindestens 10 Jahren"],"richtig":[0,1,2],"erklaerung":"Prüfung (§ 4), gleichwertiger Abschluss (§ 6) oder 3 Jahre leitende Tätigkeit (§ 7 PBZugV). Reine Fahrerfahrung reicht nicht.","quelle":"§§ 4, 6, 7 PBZugV","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-04","typ":"single","frage":"Innerhalb welcher Frist muss die Behörde über einen Antrag auf Genehmigung entscheiden?","optionen":["4 Wochen","3 Monate, einmal verlängerbar um höchstens 3 Monate","6 Monate, beliebig verlängerbar","Es gibt keine Frist."],"richtig":1,"erklaerung":"Die Frist beträgt 3 Monate und kann um höchstens 3 Monate verlängert werden. Entscheidet die Behörde nicht rechtzeitig, gilt die Genehmigung als erteilt.","quelle":"§ 15 Abs. 1 PBefG","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-05","typ":"single","frage":"Wie hoch kann das Bußgeld für eine Personenbeförderung ohne Genehmigung höchstens sein?","optionen":["1.000 €","5.000 €","10.000 €","20.000 €"],"fest":true,"richtig":3,"erklaerung":"Beförderung ohne Genehmigung: bis 20.000 €. Die meisten anderen Verstöße gegen das PBefG: bis 10.000 €.","quelle":"§ 61 Abs. 2 PBefG","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-06","typ":"multi","frage":"Welche Voraussetzungen nennt § 13 Abs. 1 PBefG für die Genehmigung? Wähle alle richtigen.","optionen":["Sicherheit und Leistungsfähigkeit des Betriebs","Zuverlässigkeit","Fachliche Eignung","Betriebssitz oder Niederlassung im Inland","Deutsche Staatsangehörigkeit","Mindestens ein Jahr Fahrpraxis als Taxifahrer"],"richtig":[0,1,2,3],"erklaerung":"Das sind die vier Voraussetzungen. Staatsangehörigkeit und Fahrpraxis sind keine Voraussetzungen.","quelle":"§ 13 Abs. 1 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-07","typ":"single","frage":"Bei welcher IHK legst du die Fachkundeprüfung ab?","optionen":["Bei jeder IHK in Deutschland","Bei der IHK an deinem Wohnsitz","Bei der IHK am geplanten Betriebssitz","Nur bei der IHK Berlin"],"richtig":1,"erklaerung":"Für Taxi und Mietwagen ist die IHK am Wohnsitz des Bewerbers zuständig. (Bei Bussen: Arbeitsort.)","quelle":"§ 5 Abs. 4 PBZugV","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-08","typ":"tf","frage":"Ein Taxiunternehmer, der seit 3 Jahren selbst Taxis betreibt, darf seine Genehmigung einzeln an einen Kollegen verkaufen, ohne den Betrieb abzugeben.","richtig":false,"erklaerung":"Taxi-Genehmigungen dürfen nur zusammen mit dem ganzen Betrieb oder einem selbständigen Teil übertragen werden. Jede Übertragung braucht außerdem eine Genehmigung.","quelle":"§ 2 Abs. 2 und 3 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-09","typ":"single","frage":"Was muss in jedem Taxi oder Mietwagen während der Fahrt mitgeführt werden?","optionen":["Nur der Führerschein des Fahrers","Die Genehmigung oder eine gekürzte amtliche Ausfertigung davon, auf Papier oder elektronisch","Das Original der Eigenkapitalbescheinigung","Der Gewerbeschein"],"richtig":1,"erklaerung":"Bei Gelegenheitsverkehr mit Kraftfahrzeugen muss die Genehmigung oder eine gekürzte amtliche Ausfertigung mitgeführt und auf Verlangen gezeigt werden. Welche Dokumente noch dazu gehören, lernst du in Lektion 2.6.","quelle":"§ 17 Abs. 4 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-10","typ":"tf","frage":"Wenn die Behörde nicht innerhalb der Frist über den Antrag entscheidet, gilt die Genehmigung als erteilt.","richtig":true,"erklaerung":"Das nennt man Genehmigungsfiktion.","quelle":"§ 15 Abs. 1 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-11","typ":"single","frage":"Ein Taxiunternehmer stirbt. Was gilt für seine Erben?","optionen":["Der Betrieb muss sofort eingestellt werden.","Die Erben dürfen vorläufig weitermachen und müssen innerhalb von 3 Monaten nach Ablauf der Ausschlagungsfrist eine Genehmigung beantragen.","Die Genehmigung geht automatisch und unbefristet auf die Erben über.","Die IHK führt den Betrieb weiter."],"richtig":1,"erklaerung":"Die Erben dürfen den Betrieb vorläufig weiterführen. Die Frist für den Antrag beträgt 3 Monate nach Ablauf der Frist für die Ausschlagung der Erbschaft.","quelle":"§ 19 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-12","typ":"single","frage":"Was ist ein typischer Grund, warum die Behörde einen Taxiunternehmer als unzuverlässig einstuft?","optionen":["Er hat nur ein Fahrzeug.","Er hat wiederholt schwer gegen Arbeitszeitvorschriften verstoßen.","Er wohnt in einer anderen Stadt als dem Betriebssitz.","Er hat keine kaufmännische Ausbildung."],"richtig":1,"erklaerung":"Schwere Verstöße gegen arbeits- und sozialrechtliche Pflichten, vor allem Arbeits- und Ruhezeiten, sind Anhaltspunkte für Unzuverlässigkeit.","quelle":"§ 1 Abs. 1 PBZugV","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-13","typ":"single","frage":"Wie lange gilt die erste Taxi-Genehmigung für einen Neubewerber?","optionen":["6 Monate","1 Jahr","2 Jahre","5 Jahre"],"fest":true,"richtig":2,"erklaerung":"Neubewerber bekommen die Genehmigung zunächst für 2 Jahre. In dieser Zeit dürfen Rechte und Pflichten nicht übertragen werden.","quelle":"§ 13 Abs. 5 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-14","typ":"tf","frage":"Die fachliche Eignung muss immer der Inhaber des Unternehmens selbst haben.","richtig":false,"erklaerung":"Es reicht, wenn die zur Führung der Geschäfte bestellte Person fachlich geeignet ist, zum Beispiel ein angestellter Betriebsleiter.","quelle":"§ 13 Abs. 1 Nr. 3 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-15","typ":"single","frage":"Wen hört die Genehmigungsbehörde bei einem Antrag für Taxi oder Mietwagen unter anderem an?","optionen":["Die Polizei und die Feuerwehr","Die IHK, die Gemeinde des Betriebssitzes, Fachgewerkschaften und Verkehrsverbände","Nur das Finanzamt","Die Krankenkasse des Antragstellers"],"richtig":1,"erklaerung":"§ 14 Abs. 2 PBefG nennt Gemeinde, Gewerbeaufsicht, IHK, Fachgewerkschaften und Verkehrsverbände. Sie haben 2 Wochen Zeit für eine Stellungnahme.","quelle":"§ 14 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-16","typ":"tf","frage":"Wer einen weiteren Mietwagen in seinen Betrieb aufnehmen will, braucht dafür keine neue Genehmigung, sondern meldet ihn nur der Zulassungsstelle.","richtig":false,"erklaerung":"Eine Erweiterung des Betriebs braucht eine Genehmigung. Die Fahrzeuge stehen mit Kennzeichen in der Genehmigungsurkunde.","quelle":"§ 2 Abs. 2 Nr. 1, § 17 PBefG","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"gb-17","typ":"offen","frage":"Nennen Sie die Voraussetzungen für die Erteilung einer Genehmigung im Taxenverkehr und erläutern Sie kurz, wie die finanzielle Leistungsfähigkeit nachgewiesen wird.","muster":"<p>Voraussetzungen nach § 13 Abs. 1 PBefG: Sicherheit und Leistungsfähigkeit des Betriebs, Zuverlässigkeit, fachliche Eignung, Betriebssitz im Inland. Beim Taxi außerdem: keine Gefährdung der Funktionsfähigkeit des örtlichen Taxengewerbes (§ 13 Abs. 4).</p><p>Finanzielle Leistungsfähigkeit: Eigenkapital und Reserven mindestens 2.250 € für das erste und 1.250 € für jedes weitere Fahrzeug, nachgewiesen durch Eigenkapitalbescheinigung (max. 1 Jahr alt) eines Steuerberaters, Wirtschaftsprüfers oder einer Bank, dazu Unbedenklichkeitsbescheinigungen von Finanzamt, Gemeinde, Krankenkassen und Berufsgenossenschaft (max. 3 Monate alt).</p>","punkte_liste":[{"t":"Sicherheit und Leistungsfähigkeit, Zuverlässigkeit, fachliche Eignung, Betriebssitz im Inland","p":2},{"t":"Taxi: Funktionsfähigkeit des örtlichen Taxengewerbes","p":1},{"t":"Beträge 2.250 € / 1.250 €","p":1},{"t":"Eigenkapitalbescheinigung (Steuerberater, WP oder Bank)","p":1},{"t":"Unbedenklichkeitsbescheinigungen (Finanzamt, Gemeinde, SV, BG)","p":1}],"quelle":"§ 13 PBefG, § 2 PBZugV","lek":"genehmigung-berufszugang","sg":"1.1"},{"id":"ka-01","typ":"single","frage":"Wo liegt die kurzfristige Preisuntergrenze für eine Fahrt?","optionen":["Bei den Selbstkosten","Bei den variablen Kosten der Fahrt","Bei 0 €","Beim Taxitarif"],"richtig":1,"erklaerung":"Kurzfristig muss der Preis mindestens die variablen Kosten decken. Langfristig müssen alle Kosten (Selbstkosten) gedeckt sein.","quelle":"Kalkulation","lc":true,"lek":"kalkulation","sg":"2.3"},{"id":"ka-02","typ":"zahl","frage":"Selbstkosten einer Mietwagenfahrt: 180 €. Gewinnzuschlag: 10 %. Wie hoch ist der Bruttopreis für einen Privatkunden?","richtig":235.62,"einheit":"€","loesung":"180,00 € × 1,10 = 198,00 € netto\n198,00 € × 1,19 = 235,62 € brutto","erklaerung":"Erst Gewinnzuschlag, dann 19 % USt (Mietwagen).","quelle":"Kalkulationsschema","lc":true,"lek":"kalkulation","sg":"2.3"},{"id":"ka-03","typ":"zahl","frage":"Ein Fahrgast zahlt in der App 35,70 € brutto. Die Plattform behält 20 % vom Nettopreis. Wie viel erhält der Mietwagenunternehmer (netto)?","richtig":24,"einheit":"€","loesung":"35,70 € ÷ 1,19 = 30,00 € netto\n30,00 € − 20 % (6,00 €) = 24,00 €","erklaerung":"Rückwärtskalkulation: erst USt herausrechnen, dann Provision abziehen.","quelle":"Rückwärtskalkulation","lc":true,"lek":"kalkulation","sg":"2.3"},{"id":"ka-04","typ":"single","frage":"Für eine App-Fahrt bleiben einem Mietwagenunternehmer nach USt und Provision 14,00 €. Die Fahrt ist 8 km lang, die Anfahrt 4 km, danach muss er ohne neuen Auftrag 6 km zum Betriebssitz zurück. Kosten: 0,85 € je km. Wie ist das Ergebnis?","optionen":["Gewinn 7,20 €","Gewinn 3,80 €","Verlust 1,30 €","Gewinn 1,30 €"],"fest":true,"richtig":2,"erklaerung":"Alle km zählen: 8 + 4 + 6 = 18 km × 0,85 € = 15,30 €. Ergebnis: 14,00 € − 15,30 € = −1,30 €. Wer nur die 8 km mit Fahrgast rechnet (7,20 €) oder die Rückfahrt vergisst (3,80 €), täuscht sich.","quelle":"Rückwärtskalkulation, § 49 Abs. 4 PBefG","lc":true,"lek":"kalkulation","sg":"2.3"},{"id":"ka-05","typ":"single","frage":"Welche Kosten soll vor allem der Zeitpreis (Wartezeit) im Taxitarif decken?","optionen":["Kraftstoff und Reifen","Fahrer- und Unternehmerlohn während das Taxi steht oder langsam fährt","Die Kfz-Steuer","Die Umsatzsteuer"],"richtig":1,"erklaerung":"Wenn das Taxi steht, fallen kaum km-Kosten an, aber die Arbeitszeit muss bezahlt werden.","quelle":"Tarifkalkulation","lek":"kalkulation","sg":"2.3"},{"id":"ka-06","typ":"zahl","frage":"Kalkuliere ein Angebot: 140 km (inkl. Leerfahrt) × 1,05 € je km, plus 2 Stunden Wartezeit × 30 € je Stunde, plus 12 % Gewinnzuschlag. Wie hoch ist der Nettopreis?","richtig":231.84,"einheit":"€","loesung":"140 × 1,05 € = 147,00 €\n2 × 30,00 € = 60,00 €\nSelbstkosten = 207,00 €\n× 1,12 = 231,84 € netto","erklaerung":"Selbstkosten aus Strecke und Zeit, dann Gewinnzuschlag.","quelle":"Angebotskalkulation","lek":"kalkulation","sg":"2.3"},{"id":"ka-07","typ":"tf","frage":"Ein Taxiunternehmer darf mit einem Hotel für Fahrten im Pflichtfahrbereich einfach mündlich einen günstigeren Festpreis als den Tarif vereinbaren.","richtig":false,"erklaerung":"Abweichungen vom Tarif im Pflichtfahrbereich sind nur als Sondervereinbarung nach § 51 Abs. 2 PBefG erlaubt, unter anderem schriftlich und mit Genehmigung oder Anzeige.","quelle":"§ 51 Abs. 2 PBefG","lek":"kalkulation","sg":"2.3"},{"id":"ka-08","typ":"zahl","frage":"Ein Bruttoangebotspreis für eine Mietwagenfahrt beträgt 297,50 €. Wie hoch ist der Nettopreis?","richtig":250,"einheit":"€","loesung":"297,50 € ÷ 1,19 = 250,00 €","erklaerung":"Mietwagen: 19 % USt.","quelle":"Kalkulation","lek":"kalkulation","sg":"2.3"},{"id":"ka-09","typ":"offen","frage":"Ein Unternehmen bittet Sie um ein Angebot für eine regelmäßige Mietwagenfahrt. Beschreiben Sie, wie Sie den Angebotspreis kalkulieren, und nennen Sie zwei typische Fehler.","muster":"<p>Selbstkosten ermitteln: alle gefahrenen km (inkl. Anfahrt und Leerfahrt) × Kosten je km, dazu Wartezeit × Stundensatz. Darauf einen Gewinnzuschlag (Gewinn, Risiko). Ergebnis = Nettopreis. Dazu 19 % Umsatzsteuer (Mietwagen) = Bruttopreis. Bei Firmenkunden Netto zzgl. USt ausweisen. Typische Fehler: Leerfahrt vergessen, 7 % statt 19 %, Gewinnzuschlag auf Brutto, Wartezeit vergessen, Kosten je Besetzt-km und je gefahrenem km verwechselt.</p>","punkte_liste":[{"t":"Selbstkosten aus km (inkl. Leerfahrt) und Zeit","p":1},{"t":"Gewinnzuschlag → Nettopreis","p":1},{"t":"+ 19 % USt → Bruttopreis","p":1},{"t":"Zwei typische Fehler genannt","p":1}],"quelle":"Kalkulation","lek":"kalkulation","sg":"2.3"},{"id":"kr-01","typ":"zuordnung","frage":"Fix oder variabel? Ordne jede Kostenart zu.","kategorien":["fix","variabel"],"paare":[{"t":"Kraftstoff","k":1,"w":"Je mehr km, desto mehr Kraftstoff. Häufiger Prüfungsfehler."},{"t":"Kfz-Haftpflichtversicherung","k":0,"w":"Jahresbeitrag, egal wie viel du fährst."},{"t":"Kfz-Steuer","k":0,"w":"Fester Jahresbetrag."},{"t":"Reifenverschleiß","k":1,"w":"Reifen nutzen sich pro km ab: Preis ÷ Laufleistung."},{"t":"Zeitabhängige Abschreibung","k":0,"w":"Das Auto verliert jedes Jahr an Wert, auch im Stand."},{"t":"Funkgebühr der Taxizentrale, monatlich pauschal","k":0,"w":"Pauschale pro Monat. Eine Gebühr pro Fahrt wäre variabel."},{"t":"Plattform-Provision (% vom Umsatz)","k":1,"w":"Steigt mit jedem Euro Umsatz."},{"t":"Kalkulatorischer Unternehmerlohn","k":0,"w":"Dein Gehalt als Chef, unabhängig von den km."},{"t":"Wartung nach km-Intervall","k":1,"w":"Inspektion alle X km, also abhängig von der Fahrleistung."}],"erklaerung":"Faustregel: Zahle ich das auch, wenn ich einen Monat gar nicht fahre? Ja = fix, Nein = variabel.","quelle":"DIHK-Orientierungsrahmen 2.2","lc":true,"lek":"kostenrechnung","sg":"2.2"},{"id":"kr-02","typ":"zahl","frage":"Ein Taxi kostet 38.000 €. Nach 5 Jahren willst du es für 8.000 € verkaufen. Wie hoch ist die jährliche Abschreibung?","richtig":6000,"einheit":"€","loesung":"(38.000 € − 8.000 €) ÷ 5 Jahre = 6.000 € pro Jahr","erklaerung":"Formel: (Anschaffungspreis − Restwert) ÷ Nutzungsdauer.","quelle":"Kostenrechnung, Abschreibung","lc":true,"lek":"kostenrechnung","sg":"2.2"},{"id":"kr-03","typ":"zahl","frage":"Gleiches Taxi: Anschaffungspreis 38.000 €, Restwert 8.000 €. Der kalkulatorische Zinssatz beträgt 6 %. Wie hoch sind die kalkulatorischen Zinsen pro Jahr?","richtig":1380,"einheit":"€","loesung":"(38.000 € + 8.000 €) ÷ 2 = 23.000 €\n23.000 € × 6 % = 1.380 €","erklaerung":"Zinsen werden auf das durchschnittlich gebundene Kapital gerechnet: (Anschaffungspreis + Restwert) ÷ 2.","quelle":"Kostenrechnung, kalkulatorische Zinsen","lc":true,"lek":"kostenrechnung","sg":"2.2"},{"id":"kr-04","typ":"zahl","frage":"Ein Taxiunternehmer fährt 60.000 km im Jahr. Seine Gesamtkosten betragen 49.000 €. Wie hoch sind die Kosten je gefahrenem km? (auf 2 Stellen gerundet)","richtig":0.82,"einheit":"€/km","loesung":"49.000 € ÷ 60.000 km = 0,8167 € ≈ 0,82 €/km","erklaerung":"Kosten je km = Gesamtkosten ÷ gefahrene km.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-05","typ":"zahl","frage":"Gleicher Betrieb: 60.000 km, Gesamtkosten 49.000 €. Die Hälfte aller km fährt er mit Fahrgast. Wie hoch sind die Kosten je Besetzt-km?","richtig":1.63,"einheit":"€/km","loesung":"Besetzt-km = 60.000 km × 50 % = 30.000 km\n49.000 € ÷ 30.000 km = 1,6333 € ≈ 1,63 €/km","erklaerung":"Nur die Besetzt-km bringen Geld. Deshalb müssen sie alle Kosten tragen.","quelle":"Kostenrechnung","lc":true,"lek":"kostenrechnung","sg":"2.2"},{"id":"kr-06","typ":"zahl","frage":"Ein Taxi erlöst im Durchschnitt 1,10 € je gefahrenem km. Die variablen Kosten betragen 0,18 € je km. Wie hoch ist der Deckungsbeitrag je km?","richtig":0.92,"einheit":"€/km","loesung":"1,10 € − 0,18 € = 0,92 € je km","erklaerung":"Deckungsbeitrag = Erlös − variable Kosten.","quelle":"Deckungsbeitragsrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-07","typ":"zahl","frage":"Die Fixkosten betragen 46.000 € im Jahr. Der Deckungsbeitrag ist 0,92 € je km. Ab wie vielen km pro Jahr macht der Betrieb Gewinn?","richtig":50000,"einheit":"km","tol":1,"loesung":"46.000 € ÷ 0,92 €/km = 50.000 km","erklaerung":"Gewinnschwelle = Fixkosten ÷ Deckungsbeitrag je km.","quelle":"Deckungsbeitragsrechnung","lc":true,"lek":"kostenrechnung","sg":"2.2"},{"id":"kr-08","typ":"zahl","frage":"Ein Mietwagenunternehmer hat Kosten von 54.000 € im Jahr. Die App behält 20 % Provision vom Umsatz. Wie viel Umsatz braucht er, um seine Kosten zu decken?","richtig":67500,"einheit":"€","loesung":"54.000 € ÷ (1 − 0,20) = 54.000 € ÷ 0,80 = 67.500 €\nProbe: 67.500 € − 20 % (13.500 €) = 54.000 € ✓","erklaerung":"Die Provision geht vom Umsatz ab. Deshalb durch (1 − Satz) teilen, nicht mit (1 + Satz) multiplizieren.","quelle":"Kostenrechnung, Provision","lc":true,"lek":"kostenrechnung","sg":"2.2"},{"id":"kr-09","typ":"single","frage":"Ein Unternehmer hat 5 Taxis. Die Miete für sein Büro gilt für alle Fahrzeuge. Wie nennt man solche Kosten?","optionen":["Einzelkosten","Gemeinkosten","Variable Kosten","Kalkulatorische Kosten"],"richtig":1,"erklaerung":"Gemeinkosten betreffen mehrere Kostenstellen und werden mit einem Schlüssel verteilt, zum Beispiel nach Anzahl der Fahrzeuge.","quelle":"Kostenstellenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-10","typ":"zahl","frage":"<p><b>Aufgabe (Beispielwerte):</b> Ein Taxi kostet 45.000 €, Restwert nach 4 Jahren 15.000 €, kalk. Zinssatz 6 %. Versicherung 5.200 €, Kfz-Steuer 220 €, Funk 2.400 €, Sonstiges 980 €, kalkulatorischer Unternehmerlohn 38.000 € pro Jahr. Verbrauch 7 l/100 km, Kraftstoff 1,60 €/l netto, Reifensatz 1.000 € für 50.000 km, Wartung 0,06 €/km. Das Taxi fährt 80.000 km im Jahr, davon 60 % mit Fahrgast.</p><p>a) Wie hoch sind die <b>Fixkosten</b> pro Jahr?</p>","richtig":56100,"einheit":"€","tol":1,"loesung":"Abschreibung = (45.000 − 15.000) ÷ 4         =  7.500 €\nZinsen      = (45.000 + 15.000) ÷ 2 × 6 %   =  1.800 €\nVersicherung                                =  5.200 €\nKfz-Steuer                                  =    220 €\nFunk                                        =  2.400 €\nSonstiges                                   =    980 €\nUnternehmerlohn                             = 38.000 €\nFixkosten                                   = 56.100 €","erklaerung":"Alle Beträge, die auch ohne Fahren anfallen, plus Abschreibung, Zinsen und Unternehmerlohn.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-11","typ":"zahl","frage":"<p>Gleiche Aufgabe. b) Wie hoch sind die <b>Kosten je gefahrenem km</b>? (2 Stellen)</p>","richtig":0.89,"einheit":"€/km","loesung":"Kraftstoff = 7 ÷ 100 × 1,60 €  = 0,112 €/km\nReifen     = 1.000 € ÷ 50.000  = 0,020 €/km\nWartung                       = 0,060 €/km\nVariable Kosten               = 0,192 €/km\n\nVariable Kosten/Jahr = 0,192 × 80.000 km = 15.360 €\nGesamtkosten = 56.100 € + 15.360 €        = 71.460 €\nKosten je km = 71.460 € ÷ 80.000 km       ≈ 0,89 €/km","erklaerung":"Erst die variablen Kosten je km, dann die Gesamtkosten, dann durch alle km teilen.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-12","typ":"zahl","frage":"<p>Gleiche Aufgabe. c) Wie hoch sind die <b>Kosten je Besetzt-km</b>? (2 Stellen)</p>","richtig":1.49,"einheit":"€/km","loesung":"Besetzt-km = 80.000 km × 60 % = 48.000 km\n71.460 € ÷ 48.000 km ≈ 1,49 €/km","erklaerung":"Gesamtkosten nur durch die km mit Fahrgast teilen.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-13","typ":"tf","frage":"Kalkulatorische Zinsen setzt man nur an, wenn der Unternehmer einen Kredit aufgenommen hat.","richtig":false,"erklaerung":"Kalkulatorische Zinsen stehen für das Geld, das im Betrieb gebunden ist und anderswo Zinsen bringen könnte. Sie werden auch bei Eigenkapital angesetzt.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-14","typ":"single","frage":"Eine Abschreibung wird nach gefahrenen Kilometern berechnet. Wie ordnest du sie ein?","optionen":["Fixkosten","Variable Kosten","Gemeinkosten","Sie gehört nicht in die Kostenrechnung."],"richtig":1,"erklaerung":"Leistungsabhängige Abschreibung steigt mit jedem km und ist deshalb variabel. Die zeitabhängige Abschreibung ist fix.","quelle":"Kostenrechnung, Abschreibung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-15","typ":"zahl","frage":"Ein Mietwagen kostet 40.000 € und soll in seiner Nutzungszeit 300.000 km fahren. Der Restwert beträgt dann 10.000 €. Wie hoch ist die leistungsabhängige Abschreibung je km?","richtig":0.1,"einheit":"€/km","tol":0.001,"dez":3,"loesung":"(40.000 € − 10.000 €) ÷ 300.000 km = 0,10 €/km","erklaerung":"Leistungsabhängig: (Anschaffungspreis − Restwert) ÷ Gesamtlaufleistung.","quelle":"Kostenrechnung, Abschreibung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-16","typ":"zahl","frage":"Ein Taxi hat Gesamtkosten von 63.000 € im Jahr und macht 4.200 Fahrten. Wie hoch sind die Kosten je Fahrt?","richtig":15,"einheit":"€","loesung":"63.000 € ÷ 4.200 Fahrten = 15,00 € je Fahrt","erklaerung":"Kosten je Fahrt = Gesamtkosten ÷ Anzahl der Fahrten.","quelle":"Kostenträgerrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-17","typ":"single","frage":"Was ist in der Kostenträgerrechnung eines Taxibetriebs der Kostenträger?","optionen":["Die Kfz-Versicherung","Das Büro","Die einzelne Fahrt oder der einzelne Kilometer","Die Bank, die den Kredit gibt"],"richtig":2,"erklaerung":"Die Kostenträgerrechnung fragt: Wofür sind die Kosten entstanden? Das ist die Leistung, also die Fahrt oder der km.","quelle":"Kostenträgerrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-18","typ":"zahl","frage":"Ein Fahrzeug verbraucht 8 Liter auf 100 km. Der Liter kostet 1,45 € netto. Wie hoch sind die Kraftstoffkosten je km? (3 Stellen)","richtig":0.116,"einheit":"€/km","tol":0.0005,"dez":3,"loesung":"8 l ÷ 100 km × 1,45 €/l = 0,116 €/km","erklaerung":"Verbrauch je 100 km erst durch 100 teilen, dann mit dem Literpreis malnehmen.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-19","typ":"single","frage":"Die Kosten eines Mietwagenbetriebs betragen 80.000 €. Die Plattform behält 25 % Provision. Welche Rechnung ergibt den nötigen Umsatz?","optionen":["80.000 € × 1,25","80.000 € ÷ 0,75","80.000 € + 25 €","80.000 € × 0,75"],"richtig":1,"erklaerung":"Umsatz = Kosten ÷ (1 − 0,25) = 106.666,67 €. Probe: davon 25 % Provision = 26.666,67 €, Rest 80.000 €.","quelle":"Kostenrechnung, Provision","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-20","typ":"tf","frage":"In der Kostenrechnung rechnet man mit Bruttobeträgen, also inklusive Umsatzsteuer.","richtig":false,"erklaerung":"Die Umsatzsteuer ist für vorsteuerabzugsberechtigte Unternehmer ein durchlaufender Posten. Kostenrechnung immer netto.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-21","typ":"offen","frage":"Erklären Sie, was der kalkulatorische Unternehmerlohn ist und warum er in die Kostenrechnung gehört.","muster":"<p>Der kalkulatorische Unternehmerlohn ist ein gedachtes Gehalt für die Arbeit des Unternehmers, der selbst im Betrieb mitarbeitet. Er wird nicht ausgezahlt und taucht nicht in der Buchhaltung auf. In der Kostenrechnung wird er als Fixkosten angesetzt, damit die Preise auch die eigene Arbeit bezahlen. Seine Höhe entspricht dem Gehalt eines vergleichbaren Angestellten.</p>","punkte_liste":[{"t":"Gedachtes Gehalt für die eigene Arbeit des Unternehmers","p":1},{"t":"Wird nicht ausgezahlt / ist kein Aufwand in der Buchführung","p":1},{"t":"Damit die Preise auch die eigene Arbeitsleistung decken","p":1},{"t":"Höhe: wie Gehalt eines vergleichbaren Angestellten; gehört zu den Fixkosten","p":1}],"quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"kr-22","typ":"offen","frage":"Erklären Sie den Unterschied zwischen fixen und variablen Kosten. Nennen Sie je zwei Beispiele aus dem Taxibetrieb.","muster":"<p>Fixe Kosten fallen unabhängig von der Fahrleistung an, z. B. Kfz-Steuer, Versicherung, zeitabhängige Abschreibung, Unternehmerlohn. Variable Kosten hängen von der Fahrleistung oder vom Umsatz ab, z. B. Kraftstoff, Reifen, Wartung nach km, Provision.</p>","punkte_liste":[{"t":"Fixe Kosten: unabhängig von der Fahrleistung","p":1},{"t":"Zwei richtige Beispiele für fixe Kosten","p":1},{"t":"Variable Kosten: abhängig von km oder Umsatz","p":1},{"t":"Zwei richtige Beispiele für variable Kosten","p":1}],"quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2"},{"id":"pz-01","typ":"single","frage":"Ein Fahrgast mit deutschem Wohnsitz und türkischer Staatsangehörigkeit fährt mit dem Taxi nach Maastricht. Welche Papiere braucht er?","optionen":["Nur seinen Führerschein","Reisepass und Aufenthaltstitel","Keine, im Schengen-Raum gibt es keine Ausweispflicht","Nur eine Kopie des Personalausweises"],"richtig":1,"erklaerung":"Drittstaatsangehörige brauchen ihren Pass und einen gültigen Aufenthaltstitel. Ein Führerschein ist kein Ausweis.","quelle":"Pass- und Aufenthaltsrecht","lc":true,"lek":"pass-zoll","sg":"5.2"},{"id":"pz-02","typ":"single","frage":"Welche Richtmenge gilt für Zigaretten, die man für den eigenen Bedarf aus einem anderen EU-Staat mitbringt?","optionen":["200 Stück","400 Stück","800 Stück","Unbegrenzt"],"fest":true,"richtig":2,"erklaerung":"800 Zigaretten innerhalb der EU. Aus Drittstaaten: 200 Stück.","quelle":"Zollrecht","lc":true,"lek":"pass-zoll","sg":"5.2"},{"id":"pz-03","typ":"tf","frage":"Weil Cannabis in Deutschland seit 2024 teilweise legal ist, darf ein Fahrgast kleine Mengen aus einem niederländischen Coffeeshop nach Deutschland mitbringen.","richtig":false,"erklaerung":"Besitz kleiner Mengen ist in Deutschland für Erwachsene erlaubt, die Einfuhr aber nicht.","quelle":"KCanG","lc":true,"lek":"pass-zoll","sg":"5.2"},{"id":"pz-04","typ":"tf","frage":"Seit September 2024 kann die Bundespolizei an der deutsch-niederländischen und deutsch-belgischen Grenze wieder Kontrollen durchführen.","richtig":true,"erklaerung":"Vorübergehende Binnengrenzkontrollen an allen deutschen Landgrenzen seit 16.9.2024, mehrfach verlängert.","quelle":"Schengener Grenzkodex","lek":"pass-zoll","sg":"5.2"},{"id":"pz-05","typ":"single","frage":"Ist ein Führerschein ein gültiges Ausweisdokument für den Grenzübertritt?","optionen":["Ja, innerhalb der EU immer","Nein, man braucht Personalausweis oder Reisepass","Nur der Führerschein zur Fahrgastbeförderung","Nur in Belgien"],"richtig":1,"erklaerung":"Der Führerschein weist nur die Fahrerlaubnis nach, nicht die Identität für Grenzzwecke.","quelle":"Passrecht","lek":"pass-zoll","sg":"5.2"},{"id":"pz-06","typ":"multi","frage":"Welche Waren dürfen nicht bzw. nur mit Erlaubnis über die Grenze mitgenommen werden? Wähle alle richtigen.","optionen":["Betäubungsmittel","Waffen und Munition","Nicht zugelassenes Feuerwerk","Ein Kasten Bier für den eigenen Bedarf","Kaffee für den eigenen Bedarf"],"richtig":[0,1,2],"erklaerung":"Waren für den eigenen Bedarf innerhalb der EU sind grundsätzlich frei.","quelle":"Zollrecht, BtMG, WaffG, SprengG","lek":"pass-zoll","sg":"5.2"},{"id":"pa-01","typ":"single","frage":"Ein Prüfling hat in Teil 1 27 von 60 Punkten und in Teil 2 45 von 52,5 Punkten. Was gilt?","optionen":["Bestanden, weil zusammen 72 Punkte","Mündliche Prüfung, weil unter 90 Punkte","Nicht bestanden, weil Teil 1 unter 50 % liegt","Bestanden, weil Teil 2 sehr gut ist"],"richtig":2,"erklaerung":"Jeder schriftliche Teil braucht mindestens 50 %. Teil 1 hat 27 von 60 = 45 %. Die mündliche Prüfung entfällt dann.","quelle":"§ 4 Abs. 4 und 5 PBZugV","lc":true,"lek":"pruefung-ablauf","sg":"–"},{"id":"pa-02","typ":"multi","frage":"Welche Tipps helfen bei Rechenaufgaben in der Prüfung? Wähle alle richtigen.","optionen":["Jeden Schritt mit Formel und Einheit aufschreiben","Erst am Ende runden","Ergebnis auf Plausibilität prüfen","Nur das Endergebnis hinschreiben, das spart Zeit","Mit Bruttobeträgen rechnen, wenn nichts angegeben ist"],"richtig":[0,1,2],"erklaerung":"Für den Rechenweg gibt es Teilpunkte. Kostenrechnung ohne Angabe: netto.","quelle":"Prüfungstaktik","lc":true,"lek":"pruefung-ablauf","sg":"–"},{"id":"pa-03","typ":"zahl","frage":"Ein Prüfling hat schriftlich 38 Punkte in Teil 1 und 32 Punkte in Teil 2. Wie viele Punkte braucht er in der mündlichen Prüfung mindestens, um zu bestehen?","richtig":20,"einheit":"Punkte","tol":0.01,"dez":0,"loesung":"Schriftlich: 38 + 32 = 70\nNötig: 90 − 70 = 20 Punkte (von 37,5)","erklaerung":"Beide Teile über 50 % (30 bzw. 26,25), zusammen unter 90 → mündlich. Gesamt mindestens 90.","quelle":"§ 4 PBZugV","lek":"pruefung-ablauf","sg":"–"},{"id":"pa-04","typ":"single","frage":"Bei welcher IHK legt ein Bewerber die Fachkundeprüfung für Taxi und Mietwagen ab?","optionen":["Bei der IHK am Betriebssitz","Bei der IHK am Wohnsitz","Bei jeder IHK nach Wahl","Nur beim DIHK in Berlin"],"richtig":1,"erklaerung":"§ 5 Abs. 4 PBZugV: Wohnsitz (bei Bussen: Arbeitsort).","quelle":"§ 5 Abs. 4 PBZugV","lek":"pruefung-ablauf","sg":"–"},{"id":"pa-05","typ":"tf","frage":"Wer schriftlich mindestens 90 Punkte erreicht und in beiden Teilen über 50 % liegt, muss nicht mehr in die mündliche Prüfung.","richtig":true,"erklaerung":"Die mündliche Prüfung entfällt, wenn schon 60 % der Gesamtpunkte erreicht sind.","quelle":"§ 4 Abs. 5 PBZugV","lek":"pruefung-ablauf","sg":"–"},{"id":"sv-01","typ":"zuordnung","frage":"Wer zahlt die Beiträge? Ordne zu.","kategorien":["Arbeitgeber und Arbeitnehmer","nur Arbeitgeber"],"paare":[{"t":"Rentenversicherung","k":0,"w":"18,6 %, je zur Hälfte."},{"t":"Arbeitslosenversicherung","k":0,"w":"2,6 %, je zur Hälfte."},{"t":"Krankenversicherung","k":0,"w":"14,6 % + Zusatzbeitrag, je zur Hälfte."},{"t":"Unfallversicherung (Berufsgenossenschaft)","k":1,"w":"Zahlt der Arbeitgeber allein."},{"t":"Umlage U1 (Erstattung bei Krankheit)","k":1,"w":"Umlagen zahlt der Arbeitgeber allein."},{"t":"Pflegeversicherung (Grundbeitrag)","k":0,"w":"3,6 %, je zur Hälfte; der Kinderlosenzuschlag geht nur zu Lasten des Arbeitnehmers."}],"erklaerung":"Merke: Unfallversicherung und Umlagen trägt nur der Arbeitgeber.","quelle":"SGB IV, VII","lc":true,"lek":"sozialversicherung","sg":"1.5"},{"id":"sv-02","typ":"single","frage":"Bis wann muss ein Taxiunternehmer einen neuen Fahrer per Sofortmeldung melden?","optionen":["Spätestens bei Beginn der Beschäftigung","Innerhalb von 2 Wochen","Mit der ersten Lohnabrechnung","Innerhalb von 6 Wochen"],"richtig":0,"erklaerung":"Im Personenbeförderungsgewerbe gilt die Sofortmeldepflicht: spätestens bei Aufnahme der Beschäftigung an die Datenstelle der Rentenversicherung.","quelle":"§ 28a Abs. 4 SGB IV","lc":true,"lek":"sozialversicherung","sg":"1.5"},{"id":"sv-03","typ":"single","frage":"An wen zahlt der Arbeitgeber den Gesamtsozialversicherungsbeitrag für einen sozialversicherungspflichtigen Fahrer?","optionen":["An das Finanzamt","An die Krankenkasse des Arbeitnehmers als Einzugsstelle","Direkt an die Rentenversicherung","An die Berufsgenossenschaft"],"richtig":1,"erklaerung":"Die Krankenkasse ist Einzugsstelle und verteilt die Beiträge an Renten-, Arbeitslosen- und Pflegeversicherung. Die Unfallversicherung geht an die BG.","quelle":"§ 28h SGB IV","lc":true,"lek":"sozialversicherung","sg":"1.5"},{"id":"sv-04","typ":"single","frage":"Ein Unternehmer lässt Fahrer als „Subunternehmer“ in seinen Taxis fahren. Er bestimmt die Schichten, die Fahrer haben kein eigenes Fahrzeug und keine eigenen Kunden. Was droht bei einer Prüfung?","optionen":["Nichts, weil Verträge mit Subunternehmern bestehen","Einstufung als Arbeitnehmer; Nachzahlung der Beiträge inklusive Arbeitnehmeranteil, Säumniszuschläge, eventuell Strafverfahren","Nur ein Hinweis der IHK","Die Fahrer müssen die Beiträge allein nachzahlen."],"richtig":1,"erklaerung":"Das ist typische Scheinselbständigkeit. Nachforderung bis 4 Jahre, bei Vorsatz bis 30 Jahre. Vorenthalten von Beiträgen ist nach § 266a StGB strafbar.","quelle":"§§ 7, 25 SGB IV, § 266a StGB","lc":true,"lek":"sozialversicherung","sg":"1.5"},{"id":"sv-05","typ":"single","frage":"Wie hoch ist der Beitragssatz zur Rentenversicherung 2026?","optionen":["9,3 %","14,6 %","18,6 %","20,0 %"],"fest":true,"richtig":2,"erklaerung":"18,6 %, je zur Hälfte von Arbeitgeber und Arbeitnehmer (je 9,3 %).","quelle":"Rechengrößen 2026","lek":"sozialversicherung","sg":"1.5"},{"id":"sv-06","typ":"tf","frage":"Ein Taxiunternehmer ohne Angestellte muss nicht bei der Berufsgenossenschaft versichert sein.","richtig":false,"erklaerung":"Taxi- und Mietwagenunternehmer sind kraft Satzung der BG Verkehr selbst pflichtversichert. Das Bundesverfassungsgericht hat das für Taxiunternehmer bestätigt.","quelle":"Satzung BG Verkehr, § 3 SGB VII","lek":"sozialversicherung","sg":"1.5"},{"id":"sv-07","typ":"single","frage":"Wann ist der Gesamtsozialversicherungsbeitrag fällig?","optionen":["Am 15. des Folgemonats","Am drittletzten Bankarbeitstag des Monats, in dem gearbeitet wurde","Einmal im Jahr am 31. Dezember","Am 10. des Folgemonats, wie die Umsatzsteuer"],"richtig":1,"erklaerung":"§ 23 Abs. 1 SGB IV: drittletzter Bankarbeitstag des laufenden Monats.","quelle":"§ 23 SGB IV","lek":"sozialversicherung","sg":"1.5"},{"id":"sv-08","typ":"single","frage":"Ein selbständiger Mietwagenunternehmer hat keine Angestellten und fährt fast ausschließlich Aufträge einer einzigen Plattform. Was sollte er prüfen lassen?","optionen":["Ob er Kindergeld bekommt","Ob er als arbeitnehmerähnlicher Selbständiger rentenversicherungspflichtig ist","Ob er Mehrwertsteuer sparen kann","Ob er einen Fahrtenschreiber braucht"],"richtig":1,"erklaerung":"Selbständige ohne versicherungspflichtige Arbeitnehmer, die im Wesentlichen nur für einen Auftraggeber tätig sind, sind rentenversicherungspflichtig.","quelle":"§ 2 Satz 1 Nr. 9 SGB VI","lek":"sozialversicherung","sg":"1.5"},{"id":"sv-09","typ":"tf","frage":"Für Minijobber muss im Taxigewerbe keine Sofortmeldung abgegeben werden.","richtig":false,"erklaerung":"Die Sofortmeldung gilt für alle Beschäftigten im Personenbeförderungsgewerbe, auch für Minijobber.","quelle":"§ 28a Abs. 4 SGB IV","lek":"sozialversicherung","sg":"1.5"},{"id":"sv-10","typ":"zahl","frage":"Ein Fahrer verdient 2.500 € brutto im Monat. Wie hoch ist der Arbeitgeberanteil zur Rentenversicherung 2026?","richtig":232.5,"einheit":"€","loesung":"18,6 % ÷ 2 = 9,3 %\n2.500 € × 9,3 % = 232,50 €","erklaerung":"Arbeitgeber und Arbeitnehmer zahlen je die Hälfte.","quelle":"SGB VI, Beitragssatz 2026","lek":"sozialversicherung","sg":"1.5"},{"id":"sv-11","typ":"offen","frage":"Welche Meldepflichten hat ein Taxiunternehmer, wenn er einen neuen sozialversicherungspflichtigen Fahrer einstellt?","muster":"<p>Betriebsnummer bei der Bundesagentur für Arbeit (falls noch nicht vorhanden). Sofortmeldung spätestens bei Beschäftigungsbeginn an die Datenstelle der Rentenversicherung (§ 28a Abs. 4 SGB IV, Personenbeförderungsgewerbe). Anmeldung bei der Krankenkasse (Einzugsstelle) mit der ersten Lohnabrechnung, spätestens innerhalb von 6 Wochen (DEÜV). Beitragsnachweis und Zahlung zum drittletzten Bankarbeitstag. Lohnnachweis an die Berufsgenossenschaft. Bei Ende: Abmeldung.</p>","punkte_liste":[{"t":"Sofortmeldung spätestens bei Beschäftigungsbeginn","p":2},{"t":"Anmeldung bei der Krankenkasse (spätestens 6 Wochen / erste Abrechnung)","p":1},{"t":"Betriebsnummer, Beitragsnachweis oder Meldung an die BG","p":1}],"quelle":"§ 28a SGB IV, DEÜV","lek":"sozialversicherung","sg":"1.5"},{"id":"st-01","typ":"zuordnung","frage":"Welcher Umsatzsteuersatz gilt?","kategorien":["7 %","19 %"],"paare":[{"t":"Taxi innerhalb der Stadt Aachen, 15 km","k":0,"w":"Taxi innerhalb einer Gemeinde."},{"t":"Taxi von Aachen nach Eschweiler, 18 km","k":0,"w":"Andere Gemeinde, aber nicht mehr als 50 km."},{"t":"Taxi von Aachen nach Köln, 72 km","k":1,"w":"Über 50 km und nicht innerhalb einer Gemeinde."},{"t":"Mietwagen innerhalb von Aachen, 6 km","k":1,"w":"Mietwagen fallen nicht unter § 12 Abs. 2 Nr. 10 UStG."},{"t":"Taxi innerhalb von Berlin, 55 km","k":0,"w":"Innerhalb einer Gemeinde gilt 7 %, auch über 50 km."}],"erklaerung":"7 % nur für Taxen: innerhalb einer Gemeinde ODER Strecke höchstens 50 km.","quelle":"§ 12 Abs. 2 Nr. 10 UStG","lc":true,"lek":"steuern","sg":"1.8"},{"id":"st-02","typ":"zahl","frage":"Ein Fahrgast zahlt für eine Taxifahrt in der Stadt 32,10 €. Wie viel Umsatzsteuer ist darin enthalten?","richtig":2.1,"einheit":"€","loesung":"32,10 € × 7 ÷ 107 = 2,10 €","erklaerung":"Aus dem Bruttobetrag: × Steuersatz ÷ (100 + Steuersatz).","quelle":"§ 12 UStG","lc":true,"lek":"steuern","sg":"1.8"},{"id":"st-03","typ":"zahl","frage":"Ein Taxiunternehmer hat im Quartal 3.120 € Umsatzsteuer eingenommen. Er hat 980 € Vorsteuer bezahlt. Wie hoch ist die Zahllast?","richtig":2140,"einheit":"€","tol":0.5,"loesung":"3.120 € − 980 € = 2.140 €","erklaerung":"Zahllast = Umsatzsteuer − Vorsteuer.","quelle":"§§ 15, 18 UStG","lc":true,"lek":"steuern","sg":"1.8"},{"id":"st-04","typ":"multi","frage":"Was gilt für Kleinunternehmer nach § 19 UStG? Wähle alle richtigen.","optionen":["Umsatz im Vorjahr höchstens 25.000 €","Umsatz im laufenden Jahr höchstens 100.000 €","Kein Ausweis von Umsatzsteuer","Kein Vorsteuerabzug","Pflicht zu monatlicher Voranmeldung"],"richtig":[0,1,2,3],"erklaerung":"Kleinunternehmer sind von der Umsatzsteuer befreit, dürfen aber auch keine Vorsteuer abziehen. Voranmeldungen entfallen.","quelle":"§ 19 UStG","lc":true,"lek":"steuern","sg":"1.8"},{"id":"st-05","typ":"multi","frage":"Was muss auf einer Taxiquittung über 38,50 € mindestens stehen? Wähle alle richtigen.","optionen":["Vollständiger Name und Anschrift des Unternehmers","Ausstellungsdatum","Art und Umfang der Leistung","Entgelt und Steuerbetrag in einer Summe","Steuersatz","Name und Anschrift des Fahrgasts","Fortlaufende Rechnungsnummer"],"richtig":[0,1,2,3,4],"erklaerung":"Bis 250 € brutto reicht eine Kleinbetragsrechnung nach § 33 UStDV. Name des Kunden und Rechnungsnummer sind dort nicht nötig.","quelle":"§ 33 UStDV","lc":true,"lek":"steuern","sg":"1.8"},{"id":"st-06","typ":"tf","frage":"Seit dem 1. Januar 2026 muss jeder Taxameter mit einer zertifizierten technischen Sicherheitseinrichtung (TSE) ausgestattet sein.","richtig":true,"erklaerung":"Die Übergangsregel für EU-Taxameter endete am 31.12.2025. Taxameter und Wegstreckenzähler sind elektronische Aufzeichnungssysteme nach § 146a AO.","quelle":"§ 146a AO, KassenSichV","lc":true,"lek":"steuern","sg":"1.8"},{"id":"st-07","typ":"zahl","frage":"Ein Einzelunternehmer hat einen Gewerbeertrag von 60.000 €. Der Hebesatz beträgt 400 %. Wie hoch ist die Gewerbesteuer?","richtig":4970,"einheit":"€","tol":0.5,"loesung":"60.000 € − 24.500 € = 35.500 €\n35.500 € × 3,5 % = 1.242,50 € Messbetrag\n1.242,50 € × 400 % = 4.970,00 €","erklaerung":"(Gewerbeertrag − Freibetrag) × Messzahl × Hebesatz.","quelle":"§§ 11, 16 GewStG","lc":true,"lek":"steuern","sg":"1.8"},{"id":"st-08","typ":"zahl","frage":"Ein Kunde zahlt für eine Mietwagenfahrt 142,80 € brutto. Wie hoch ist der Nettobetrag?","richtig":120,"einheit":"€","loesung":"142,80 € ÷ 1,19 = 120,00 €","erklaerung":"Mietwagen: 19 %. Netto = Brutto ÷ 1,19.","quelle":"§ 12 Abs. 1 UStG","lek":"steuern","sg":"1.8"},{"id":"st-09","typ":"tf","frage":"Eine Taxiquittung gilt umsatzsteuerlich als Fahrausweis nach § 34 UStDV.","richtig":false,"erklaerung":"Rechnungen über die Benutzung eines Taxis oder Mietwagens sind keine Fahrausweise (UStAE 14.7). Bis 250 € sind sie Kleinbetragsrechnungen.","quelle":"UStAE 14.7, § 33 UStDV","lek":"steuern","sg":"1.8"},{"id":"st-10","typ":"single","frage":"Bis wann muss die Umsatzsteuer-Voranmeldung für das 2. Quartal (ohne Dauerfristverlängerung) beim Finanzamt sein?","optionen":["30. Juni","10. Juli","31. Juli","10. August"],"richtig":1,"erklaerung":"Bis zum 10. Tag nach Ablauf des Voranmeldungszeitraums.","quelle":"§ 18 Abs. 1 UStG","lek":"steuern","sg":"1.8"},{"id":"st-11","typ":"single","frage":"Wann muss ein Unternehmer die Umsatzsteuer-Voranmeldung monatlich abgeben?","optionen":["Immer","Wenn die Steuer im Vorjahr mehr als 9.000 € betrug","Wenn er mehr als 2 Fahrzeuge hat","Nur im ersten Jahr"],"richtig":1,"erklaerung":"Regelzeitraum ist das Kalendervierteljahr; monatlich bei Vorjahressteuer über 9.000 €.","quelle":"§ 18 Abs. 2 UStG","lek":"steuern","sg":"1.8"},{"id":"st-12","typ":"single","frage":"Für welche Unternehmen gilt der Freibetrag von 24.500 € bei der Gewerbesteuer?","optionen":["Für alle Unternehmen","Für Einzelunternehmen und Personengesellschaften","Nur für GmbH","Nur für Kleinunternehmer nach § 19 UStG"],"richtig":1,"erklaerung":"Natürliche Personen und Personengesellschaften. Kapitalgesellschaften erhalten keinen Freibetrag.","quelle":"§ 11 Abs. 1 GewStG","lek":"steuern","sg":"1.8"},{"id":"st-13","typ":"single","frage":"Ein Taxiunternehmer kauft ein neues Elektro-Taxi mit Erstzulassung im Jahr 2026. Was gilt für die Kfz-Steuer?","optionen":["Volle Kfz-Steuer nach Gewicht","Befreit für 10 Jahre ab Erstzulassung, längstens bis 31.12.2035","Befreit für immer","Nur halbe Kfz-Steuer"],"richtig":1,"erklaerung":"§ 3d KraftStG: Erstzulassung bis 31.12.2030, Befreiung 10 Jahre, längstens bis 31.12.2035.","quelle":"§ 3d KraftStG","lek":"steuern","sg":"1.8"},{"id":"st-14","typ":"single","frage":"Wer ist für die Kfz-Steuer zuständig?","optionen":["Das Finanzamt","Die Gemeinde","Der Zoll (Hauptzollamt)","Die Zulassungsstelle"],"richtig":2,"erklaerung":"Die Kfz-Steuer verwaltet die Zollverwaltung.","quelle":"KraftStG","lek":"steuern","sg":"1.8"},{"id":"st-15","typ":"single","frage":"Wann sind die Einkommensteuer-Vorauszahlungen fällig?","optionen":["Monatlich am 10.","10. März, 10. Juni, 10. September, 10. Dezember","Einmal jährlich am 31. Mai","15. Februar, 15. Mai, 15. August, 15. November"],"richtig":1,"erklaerung":"§ 37 Abs. 1 EStG.","quelle":"§ 37 EStG","lek":"steuern","sg":"1.8"},{"id":"st-16","typ":"tf","frage":"Ein Taxiunternehmer darf die Vorsteuer aus einer Werkstattrechnung nur abziehen, wenn er eine ordnungsgemäße Rechnung hat.","richtig":true,"erklaerung":"Voraussetzung für den Vorsteuerabzug ist eine Rechnung nach §§ 14, 14a UStG.","quelle":"§ 15 Abs. 1 UStG","lek":"steuern","sg":"1.8"},{"id":"st-17","typ":"offen","frage":"Erklären Sie, wann eine Taxifahrt dem ermäßigten Umsatzsteuersatz unterliegt, und was für Mietwagenfahrten gilt. Rechnen Sie die Umsatzsteuer aus einem Fahrpreis von 53,50 € (Taxi, innerorts) heraus.","muster":"<p>Taxifahrten unterliegen 7 %, wenn sie innerhalb einer Gemeinde stattfinden oder die Beförderungsstrecke nicht mehr als 50 km beträgt (§ 12 Abs. 2 Nr. 10 UStG). Sonst 19 %. Mietwagenfahrten unterliegen grundsätzlich 19 % (Ausnahme: Krankenfahrten zu Taxi-Bedingungen). Rechnung: 53,50 € × 7 ÷ 107 = 3,50 € USt; netto 50,00 €.</p>","punkte_liste":[{"t":"7 % innerhalb einer Gemeinde","p":1},{"t":"7 % bei Strecke bis 50 km, sonst 19 %","p":1},{"t":"Mietwagen grundsätzlich 19 %","p":1},{"t":"Rechnung richtig: 3,50 € USt / 50,00 € netto","p":2}],"quelle":"§ 12 UStG","lek":"steuern","sg":"1.8"},{"id":"tb-01","typ":"single","frage":"Wer ist nach dem PBefG ermächtigt, die Beförderungsentgelte für Taxen festzulegen?","optionen":["Die IHK","Die Landesregierung durch Rechtsverordnung; sie kann die Ermächtigung übertragen","Jeder Taxiunternehmer für sich","Die örtliche Taxizentrale"],"richtig":1,"erklaerung":"§ 51 Abs. 1 PBefG ermächtigt die Landesregierung. Meist ist die Aufgabe auf Kreise und kreisfreie Städte übertragen. Die IHK wird angehört.","quelle":"§ 51 Abs. 1 und 3 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-02","typ":"tf","frage":"Ein Taxifahrer darf einem Stammkunden 10 % Rabatt auf den Taxitarif geben, wenn der Kunde regelmäßig fährt.","richtig":false,"erklaerung":"Der Tarif darf weder über- noch unterschritten werden. Ermäßigungen, die nicht unter gleichen Bedingungen jedem zugutekommen, sind verboten. Möglich wäre nur eine Sondervereinbarung nach § 51 Abs. 2.","quelle":"§ 51 Abs. 5, § 39 Abs. 3 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-03","typ":"multi","frage":"Unter welchen Bedingungen sind Sondervereinbarungen für den Pflichtfahrbereich zulässig? Wähle alle richtigen.","optionen":["Es gibt einen festen Zeitraum, eine Mindestzahl an Fahrten oder einen Mindestumsatz im Monat.","Die Ordnung des Verkehrsmarktes wird nicht gestört.","Entgelte und Bedingungen werden schriftlich vereinbart.","Die Rechtsverordnung sieht eine Genehmigung oder Anzeige vor.","Der Kunde zahlt bar.","Die Fahrt geht über mehr als 50 km."],"richtig":[0,1,2,3],"erklaerung":"Das sind die vier Bedingungen aus § 51 Abs. 2 PBefG.","quelle":"§ 51 Abs. 2 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-04","typ":"multi","frage":"Wann besteht nach § 22 PBefG eine Beförderungspflicht? Wähle alle Bedingungen.","optionen":["Die Beförderungsbedingungen werden eingehalten.","Die Beförderung ist mit den regelmäßig eingesetzten Fahrzeugen möglich.","Die Beförderung wird nicht durch Umstände verhindert, die der Unternehmer nicht abwenden und nicht beheben kann.","Die Fahrt ist länger als 5 km.","Der Fahrgast zahlt im Voraus."],"richtig":[0,1,2],"erklaerung":"Diese drei Bedingungen nennt § 22 PBefG. Die Länge der Fahrt spielt keine Rolle.","quelle":"§ 22 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-05","typ":"single","frage":"Ein Fahrgast ist stark betrunken, beleidigt den Fahrer und schlägt gegen die Scheibe. Was gilt?","optionen":["Der Fahrer muss ihn wegen der Beförderungspflicht trotzdem fahren.","Der Fahrer darf die Fahrt ablehnen, weil Tatsachen dafür sprechen, dass der Fahrgast eine Gefahr für die Sicherheit ist.","Der Fahrer darf nur ablehnen, wenn die Polizei zustimmt.","Der Fahrer darf ablehnen, muss aber trotzdem den Grundpreis kassieren."],"richtig":1,"erklaerung":"Die Beförderung darf abgelehnt werden, wenn Tatsachen die Annahme rechtfertigen, dass die Person eine Gefahr für Sicherheit und Ordnung oder für Fahrgäste ist.","quelle":"§ 13 BOKraft","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-06","typ":"single","frage":"Was gilt für die Preise im Mietwagenverkehr?","optionen":["Es gilt der örtliche Taxitarif.","Der Preis ist frei vereinbar; ohne Vereinbarung wird nach dem Wegstreckenzähler abgerechnet. Die Behörde kann Mindestentgelte festlegen.","Der Preis wird von der IHK festgelegt.","Mietwagen dürfen nur Festpreise nehmen, die die Behörde genehmigt hat."],"richtig":1,"erklaerung":"Mietwagen haben keine Tarifpflicht. § 40 BOKraft: Abrechnung nach Wegstreckenzähler, wenn nichts anderes vereinbart ist. § 51a PBefG: Die Behörde kann Mindestentgelte festlegen.","quelle":"§ 51a PBefG, § 40 BOKraft","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-07","typ":"single","frage":"Wann muss das Taxischild nach BOKraft leuchten?","optionen":["Immer, wenn der Motor läuft","Wenn das Taxi frei ist und im Tarifgebiet unterwegs ist; nicht nötig am Taxistand; aus bei einer Fahrt mit Auftrag","Nur nachts","Nur während der Fahrt mit Fahrgast"],"richtig":1,"erklaerung":"So erkennt man auf der Straße, ob ein Taxi frei ist.","quelle":"§ 39 BOKraft","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-08","typ":"tf","frage":"Für eine vorbestellte Taxifahrt kann der örtliche Tarif einen Festpreis oder einen Preisrahmen vorsehen. Innerhalb des Rahmens wird der Preis vor Fahrtantritt vereinbart.","richtig":true,"erklaerung":"Das erlaubt § 51 Abs. 1 Satz 4 PBefG seit der Reform 2021.","quelle":"§ 51 Abs. 1 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-09","typ":"single","frage":"Ein Fahrgast sagt nichts zur Strecke. Welchen Weg muss der Fahrer nehmen?","optionen":["Den schnellsten Weg, egal wie lang","Den kürzesten Weg; einen anderen nur, wenn er verkehrs- oder preisgünstiger ist und mit dem Fahrgast vereinbart wird","Den Weg, den das Navi zuerst vorschlägt","Jeden Weg, weil der Taxameter sowieso läuft"],"richtig":1,"erklaerung":"§ 38 BOKraft: kürzester Weg, sofern der Fahrgast nichts anderes bestimmt.","quelle":"§ 38 BOKraft","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-10","typ":"tf","frage":"Ein Taxifahrer darf eine Fahrt von 1,5 km im Pflichtfahrbereich ablehnen, weil sie sich nicht lohnt.","richtig":false,"erklaerung":"Die Länge der Fahrt ist kein Grund. Im Pflichtfahrbereich gilt die Beförderungspflicht.","quelle":"§§ 22, 47 Abs. 4 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-11","typ":"single","frage":"Ein Fahrgast will einen Kanister Benzin im Kofferraum mitnehmen. Was gilt?","optionen":["Erlaubt, wenn er dafür einen Zuschlag zahlt","Leicht entzündliche Stoffe sind von der Beförderung ausgeschlossen.","Erlaubt, wenn der Kanister geschlossen ist","Nur mit Genehmigung der Feuerwehr"],"richtig":1,"erklaerung":"Explosive, leicht entzündliche, radioaktive, übel riechende oder ätzende Stoffe sind von der Beförderung ausgeschlossen.","quelle":"§ 15 BOKraft","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-12","typ":"single","frage":"Was ist der Pflichtfahrbereich?","optionen":["Das Gebiet, in dem die Taxenordnung Halteverbote regelt","Der Geltungsbereich des festgesetzten Taxitarifs; nur dort gilt die Beförderungspflicht","Die Strecke vom Taxistand zum Betriebssitz","Das Gebiet, in dem Mietwagen warten dürfen"],"richtig":1,"erklaerung":"Die Beförderungspflicht besteht nur für Fahrten innerhalb des Geltungsbereichs der Beförderungsentgelte nach § 51.","quelle":"§ 47 Abs. 4 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-13","typ":"zahl","frage":"Beispieltarif: Grundpreis 4,00 €, 1. bis 5. km 2,40 €/km, ab dem 6. km 2,10 €/km. Ein Fahrgast fährt 9 km ohne Wartezeit. Wie hoch ist der Fahrpreis?","richtig":24.4,"einheit":"€","loesung":"4,00 € + 5 × 2,40 € + 4 × 2,10 €\n= 4,00 € + 12,00 € + 8,40 € = 24,40 €","erklaerung":"Grundpreis plus gestaffelte km-Preise.","quelle":"Beispieltarif (Beispielwerte)","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-14","typ":"tf","frage":"Die Beförderungspflicht gilt auch für Mietwagen, wenn der Auftrag am Betriebssitz eingeht.","richtig":false,"erklaerung":"Für Mietwagen gelten §§ 21 und 22 PBefG nicht.","quelle":"§ 49 Abs. 4 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-15","typ":"single","frage":"Was bedeutet die Betriebspflicht für einen Taxiunternehmer?","optionen":["Er muss jeden Tag 24 Stunden fahren.","Er muss den genehmigten Betrieb aufnehmen und während der Geltungsdauer ordnungsgemäß führen. Befreiung nur auf Antrag.","Er muss einen Betriebsrat gründen.","Er muss jedes Jahr eine Betriebsprüfung beim Finanzamt beantragen."],"richtig":1,"erklaerung":"§ 21 PBefG. Die Behörde kann auf Antrag befreien, wenn der Betrieb unmöglich oder unzumutbar ist.","quelle":"§ 21 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tb-16","typ":"offen","frage":"Erläutern Sie die Tarifpflicht im Taxenverkehr und nennen Sie zwei Ausnahmen.","muster":"<p>Die nach § 51 PBefG festgesetzten Beförderungsentgelte sind verbindlich. Sie dürfen weder über- noch unterschritten werden; Ermäßigungen sind nur zulässig, wenn sie unter gleichen Bedingungen jedermann zugutekommen (§ 51 Abs. 5 i. V. m. § 39 Abs. 3). Ausnahmen: Sondervereinbarungen nach § 51 Abs. 2 (Zeitraum/Mindestmenge, Markt nicht gestört, schriftlich, Genehmigung/Anzeige); Festpreise oder Preisrahmen für vorbestellte Fahrten (§ 51 Abs. 1 S. 4); Fahrten außerhalb des Pflichtfahrbereichs.</p>","punkte_liste":[{"t":"Tarif ist verbindlich: nicht über- und nicht unterschreiten","p":1},{"t":"Ermäßigungen nur für jedermann zu gleichen Bedingungen","p":1},{"t":"Ausnahme 1 richtig (z. B. Sondervereinbarung)","p":1},{"t":"Ausnahme 2 richtig (z. B. Festpreis/Preisrahmen bei Vorbestellung oder außerhalb Pflichtfahrbereich)","p":1}],"quelle":"§§ 39, 51 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1"},{"id":"tm-01","typ":"single","frage":"Welche Fahrt fällt <b>nicht</b> unter das Personenbeförderungsgesetz?","optionen":["Ein Mietwagen bringt einen Fahrgast gegen 40 € zum Flughafen.","Vier Kollegen fahren zusammen zur Arbeit und teilen nur die Spritkosten, weniger als 30 Cent pro km.","Ein Taxi fährt einen Fahrgast nach Taxitarif.","Ein Fahrer bietet über eine App Fahrten gegen Bezahlung an."],"richtig":1,"erklaerung":"Fahrten mit dem Pkw sind ausgenommen, wenn sie kostenlos sind oder das Gesamtentgelt nicht über dem Betrag nach § 5 Abs. 2 BRKG liegt (zurzeit 30 Cent pro km).","quelle":"§ 1 Abs. 2 Nr. 1 PBefG, § 5 Abs. 2 BRKG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-02","typ":"multi","frage":"Welche Formen des Gelegenheitsverkehrs erlaubt das PBefG? Wähle alle richtigen.","optionen":["Verkehr mit Taxen","Verkehr mit Mietwagen","Gebündelter Bedarfsverkehr","Linienverkehr mit Stadtbussen","Privates Mitnehmen von Anhaltern gegen Bezahlung"],"richtig":[0,1,2],"erklaerung":"§ 46 Abs. 2 PBefG erlaubt nur vier Formen: Taxen, Ausflugsfahrten und Ferienziel-Reisen, Mietomnibusse und Mietwagen sowie den gebündelten Bedarfsverkehr. Linienverkehr ist kein Gelegenheitsverkehr.","quelle":"§ 46 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-03","typ":"zuordnung","frage":"Für wen gilt die Regel?","kategorien":["Taxi","Mietwagen","beide"],"paare":[{"t":"Muss nach jeder Fahrt ohne neuen Auftrag zum Betriebssitz zurück.","k":1,"w":"Das ist die Rückkehrpflicht nach § 49 Abs. 4 PBefG."},{"t":"Muss jeden Fahrgast im Pflichtfahrbereich mitnehmen.","k":0,"w":"Beförderungspflicht gibt es nur beim Taxi (§§ 22, 47 Abs. 4 PBefG)."},{"t":"Braucht eine Genehmigung nach dem PBefG.","k":2,"w":"§ 2 PBefG gilt für beide."},{"t":"Muss eingehende Aufträge aufzeichnen und 1 Jahr aufbewahren.","k":1,"w":"§ 49 Abs. 4 PBefG."},{"t":"Hat einen Fahrpreisanzeiger (Taxameter).","k":0,"w":"Der Mietwagen hat einen Wegstreckenzähler (§§ 28, 30 BOKraft)."},{"t":"Darf nicht an Selbstfahrer vermietet werden.","k":0,"w":"§ 47 Abs. 5 PBefG verbietet das ausdrücklich für Taxen."},{"t":"Außenwerbung nur an den seitlichen Türen.","k":2,"w":"§ 26 Abs. 2 BOKraft gilt für Taxen und Mietwagen."},{"t":"Der Preis ist grundsätzlich frei vereinbar.","k":1,"w":"Die Behörde kann aber Mindestentgelte festlegen (§ 51a PBefG)."}],"erklaerung":"Die Tabelle in dieser Lektion fasst alle Unterschiede zusammen.","quelle":"PBefG, BOKraft","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-04","typ":"single","frage":"Ein Mietwagen aus Aachen bringt einen Fahrgast zum Flughafen Düsseldorf. Einen neuen Auftrag hat der Fahrer nicht. Was muss er tun?","optionen":["Er darf am Terminal auf neue Fahrgäste warten.","Er muss unverzüglich zum Betriebssitz in Aachen zurückfahren.","Er darf sich an den Taxistand stellen, wenn dort Platz ist.","Er darf eine Stunde warten und dann zurückfahren."],"richtig":1,"erklaerung":"Ohne neuen Auftrag gilt die Rückkehrpflicht. Warten auf Kunden ist für Mietwagen nicht erlaubt.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-05","typ":"tf","frage":"Während der Fahrt geht über die App ein neuer Auftrag am Betriebssitz ein. Der Mietwagen darf nach dem Absetzen direkt zum neuen Fahrgast fahren.","richtig":true,"erklaerung":"Die Rückkehrpflicht entfällt, wenn vor oder während der Fahrt ein neuer Auftrag über den Betriebssitz eingegangen ist.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-06","typ":"tf","frage":"Ein Passant winkt einem Mietwagen an der Ampel zu. Der Fahrer darf ihn mitnehmen, wenn er gerade frei ist.","richtig":false,"erklaerung":"Der Auftrag ist nicht über den Betriebssitz eingegangen. Fahrgäste auf der Straße aufnehmen darf nur ein Taxi.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-07","typ":"tf","frage":"Ein Aachener Taxi darf sich in Köln an einen Taxistand stellen und dort auf Fahrgäste warten.","richtig":false,"erklaerung":"Taxen dürfen grundsätzlich nur in der Gemeinde bereitgehalten werden, in der der Unternehmer seinen Betriebssitz hat. Die Behörde kann Ausnahmen erlauben.","quelle":"§ 47 Abs. 2 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-08","typ":"tf","frage":"Ein Aachener Taxi darf einen vorbestellten Fahrgast in Köln abholen und nach Aachen fahren.","richtig":true,"erklaerung":"Vorbestellte Fahrten dürfen auch in anderen Gemeinden beginnen.","quelle":"§ 47 Abs. 2 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-09","typ":"single","frage":"Ein Mietwagen hat ein gelbes Dachschild mit der Aufschrift „CAB“. Ist das erlaubt?","optionen":["Ja, solange nicht „Taxi“ draufsteht.","Nein, weil man den Mietwagen damit mit einem Taxi verwechseln kann.","Ja, wenn das Schild nachts nicht leuchtet.","Nur mit Genehmigung der IHK."],"richtig":1,"erklaerung":"Mietwagen dürfen nicht so auftreten, dass man sie mit Taxis verwechseln kann. Zeichen, die Taxen vorbehalten sind, sind verboten.","quelle":"§ 49 Abs. 4 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-10","typ":"single","frage":"Wie lange muss ein Mietwagenunternehmer die Aufzeichnungen über eingegangene Aufträge aufbewahren?","optionen":["3 Monate","6 Monate","1 Jahr","10 Jahre"],"fest":true,"richtig":2,"erklaerung":"Die Aufträge werden buchmäßig oder elektronisch erfasst und ein Jahr aufbewahrt.","quelle":"§ 49 Abs. 4 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-11","typ":"single","frage":"Welches Messgerät braucht ein Mietwagen?","optionen":["Einen Fahrpreisanzeiger (Taxameter)","Einen Wegstreckenzähler oder ein zugelassenes Software-System","Einen Fahrtenschreiber","Kein Messgerät"],"richtig":1,"erklaerung":"In Mietwagen ist ein leicht ablesbarer Wegstreckenzähler einzubauen, alternativ ein konformitätsbewertetes Software-System. Das Eichrecht gilt.","quelle":"§ 30 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-12","typ":"single","frage":"Welche Farbe schreibt die BOKraft für Taxen vor?","optionen":["Schwarz","Hell-elfenbein RAL 1015","Verkehrsgelb RAL 1023","Keine bestimmte Farbe"],"richtig":1,"erklaerung":"Taxen sind hell-elfenbein nach RAL 1015. Ausnahmen sind über Landesrecht möglich.","quelle":"§ 26 Abs. 1 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-13","typ":"single","frage":"Ein Mietwagenfahrer lehnt eine Fahrt von Aachen nach Maastricht ab. Darf er das?","optionen":["Nein, er hat Beförderungspflicht.","Ja, für Mietwagen gibt es keine Beförderungspflicht.","Nur wenn die Fahrt länger als 50 km ist.","Nur nach 22 Uhr."],"richtig":1,"erklaerung":"§§ 21 und 22 PBefG (Betriebs- und Beförderungspflicht) gelten für Mietwagen nicht.","quelle":"§ 49 Abs. 4 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-14","typ":"single","frage":"In einer großen Flächengemeinde darf die Behörde Abstellorte für Mietwagen erlauben. Welcher Mindestabstand zum Betriebssitz ist dafür die Grundlage?","optionen":["5 km","10 km","15 km","50 km"],"fest":true,"richtig":2,"erklaerung":"Grundlage ist ein Mindestabstand von 15 km zwischen dem Hauptbetriebssitz und dem Abstellort oder zwischen mehreren Abstellorten.","quelle":"§ 49 Abs. 5 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-15","typ":"tf","frage":"Uber und Bolt brauchen in Deutschland selbst keine Genehmigung, deshalb braucht auch der Mietwagenunternehmer, der über diese Apps fährt, keine Genehmigung.","richtig":false,"erklaerung":"Die Plattform vermittelt nur. Wer die Fahrten gegen Entgelt ausführt, ist Unternehmer und braucht eine Genehmigung nach § 2 PBefG.","quelle":"§§ 2, 49 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-16","typ":"offen","frage":"Erklären Sie die Rückkehrpflicht für Mietwagen. Nennen Sie auch, wann sie nicht gilt.","muster":"<p>Mietwagen dürfen nur Aufträge ausführen, die am Betriebssitz oder in der Wohnung des Unternehmers eingegangen sind. Nach Ende der Fahrt muss der Mietwagen unverzüglich zum Betriebssitz zurückkehren. Das gilt nicht, wenn der Fahrer vor der Fahrt über den Betriebssitz oder während der Fahrt einen neuen Auftrag bekommen hat. In großen Flächengemeinden kann die Behörde außerdem Abstellorte erlauben (Grundlage: mindestens 15 km Abstand).</p>","punkte_liste":[{"t":"Aufträge nur über Betriebssitz oder Wohnung des Unternehmers","p":1},{"t":"Nach der Fahrt unverzüglich zurück zum Betriebssitz","p":1},{"t":"Ausnahme: neuer Auftrag vor oder während der Fahrt","p":1},{"t":"Sonderregel: Abstellorte in Flächengemeinden (§ 49 Abs. 5)","p":1}],"quelle":"§ 49 Abs. 4 und 5 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-17","typ":"offen","frage":"Nennen Sie vier Unterschiede zwischen dem Verkehr mit Taxen und dem Verkehr mit Mietwagen.","muster":"<ul><li>Taxi darf an Taxiständen bereitstehen und auf der Straße Aufträge annehmen, Mietwagen nur über den Betriebssitz.</li><li>Mietwagen hat Rückkehrpflicht.</li><li>Taxi hat Beförderungs- und Betriebspflicht, Mietwagen nicht.</li><li>Taxi hat festen Tarif, Mietwagen freien Preis (evtl. Mindestentgelt).</li><li>Taxi: RAL 1015 und Taxischild; Mietwagen darf nicht wie ein Taxi aussehen.</li><li>Taxi: Fahrpreisanzeiger; Mietwagen: Wegstreckenzähler.</li></ul>","punkte_liste":[{"t":"Auftragsannahme / Bereithalten (Taxistand vs. Betriebssitz)","p":1},{"t":"Rückkehrpflicht beim Mietwagen","p":1},{"t":"Beförderungspflicht nur beim Taxi","p":1},{"t":"Tarifpflicht beim Taxi, freie Preise beim Mietwagen","p":1},{"t":"Weiterer richtiger Unterschied (Aussehen, Messgerät, Genehmigungsprüfung …)","p":1}],"quelle":"§§ 47, 49, 51, 51a PBefG; §§ 26, 28, 30 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"tm-18","typ":"single","frage":"Was gilt für Außenwerbung an Taxen?","optionen":["Werbung ist überall am Fahrzeug erlaubt.","Werbung nur an den seitlichen Türen, keine politische oder religiöse Werbung.","Werbung ist bei Taxen ganz verboten.","Werbung nur auf dem Dach neben dem Taxischild."],"richtig":1,"erklaerung":"Werbung nach außen ist nur an den seitlichen Fahrzeugtüren erlaubt. Politische und religiöse Werbung ist an Taxen verboten.","quelle":"§ 26 Abs. 2 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1"},{"id":"um-01","typ":"tf","frage":"Ein Taxifahrer darf am Taxenstand den Motor laufen lassen, damit das Auto warm bleibt.","richtig":false,"erklaerung":"Unnötiges Laufenlassen von Motoren ist verboten.","quelle":"§ 30 Abs. 1 StVO","lc":true,"lek":"umweltschutz","sg":"4.3"},{"id":"um-02","typ":"single","frage":"Wo sollen Taxis gewaschen werden?","optionen":["Auf der Straße vor dem Betrieb","Auf einer Wiese","In einer Waschanlage oder auf einem Waschplatz mit Ölabscheider","Am Taxenstand"],"richtig":2,"erklaerung":"Sonst gelangen Öl, Kraftstoff und Reiniger ins Wasser. Grundlage ist der Gewässerschutz (WHG) und die örtliche Abwassersatzung.","quelle":"WHG","lc":true,"lek":"umweltschutz","sg":"4.3"},{"id":"um-03","typ":"zahl","frage":"Ein Taxi fährt 60.000 km im Jahr. Durch sparsame Fahrweise sinkt der Verbrauch von 7,5 auf 6,5 l/100 km. Der Liter kostet 1,50 € netto. Wie viel spart der Unternehmer im Jahr?","richtig":900,"einheit":"€","tol":0.5,"loesung":"60.000 ÷ 100 × 1,0 l = 600 l\n600 l × 1,50 € = 900,00 €","erklaerung":"Ersparnis = km ÷ 100 × Verbrauchsdifferenz × Preis.","quelle":"Kostenrechnung","lc":true,"lek":"umweltschutz","sg":"4.3"},{"id":"um-04","typ":"single","frage":"Welche Verordnung regelt die Plaketten für Umweltzonen?","optionen":["35. BImSchV","BOKraft","FeV","39. BImSchV"],"richtig":0,"erklaerung":"35. BImSchV: Kennzeichnung der Kraftfahrzeuge mit geringem Beitrag zur Schadstoffbelastung. Die 39. BImSchV regelt die Luftqualitätsgrenzwerte.","quelle":"35. BImSchV","lek":"umweltschutz","sg":"4.3"},{"id":"um-05","typ":"single","frage":"Was muss ein Händler tun, der Motoröl verkauft?","optionen":["Nichts","Altöl in der Menge des verkauften Öls zurücknehmen","Nur Öl an Werkstätten verkaufen","Altöl in den Hausmüll geben"],"richtig":1,"erklaerung":"Rücknahmepflicht nach der Altölverordnung.","quelle":"Altölverordnung","lek":"umweltschutz","sg":"4.3"},{"id":"um-06","typ":"multi","frage":"Welche Fahrweise spart Kraftstoff? Wähle alle richtigen.","optionen":["Vorausschauend fahren und rollen lassen","Früh hochschalten","Reifendruck regelmäßig prüfen","Motor beim Warten laufen lassen","Stark beschleunigen, um schneller im höchsten Gang zu sein"],"richtig":[0,1,2],"erklaerung":"Laufenlassen ist verboten und kostet Kraftstoff; starkes Beschleunigen erhöht den Verbrauch.","quelle":"Umweltschutz","lek":"umweltschutz","sg":"4.3"},{"id":"um-07","typ":"offen","frage":"Nennen Sie vier Maßnahmen, mit denen ein Taxiunternehmen die Umwelt beim Betrieb und bei der Wartung seiner Fahrzeuge schützen kann.","muster":"<ul><li>Sparsame Fahrweise schulen, Motor beim Warten aus (§ 30 StVO)</li><li>Emissionsarme Fahrzeuge (Hybrid, E) anschaffen, Umweltzonen beachten</li><li>Regelmäßige Wartung, Reifendruck, AU bei der HU</li><li>Waschen nur mit Ölabscheider</li><li>Altöl, Reifen, Batterien fachgerecht entsorgen</li><li>Lärm vermeiden am Taxenstand</li></ul>","punkte_liste":[{"t":"Maßnahme 1","p":1},{"t":"Maßnahme 2","p":1},{"t":"Maßnahme 3","p":1},{"t":"Maßnahme 4","p":1}],"quelle":"StVO, KrWG, WHG, BImSchG","lek":"umweltschutz","sg":"4.3"},{"id":"uf-01","typ":"single","frage":"Was ist nach einem Unfall mit Verletzten die richtige Reihenfolge?","optionen":["Fotos machen, Versicherung anrufen, dann helfen","Anhalten und Warnblinker, eigene Sicherheit und Absichern, Notruf, Erste Hilfe","Weiterfahren und später die Polizei anrufen","Erst die Fahrgäste abrechnen, dann helfen"],"richtig":1,"erklaerung":"Erst sichern und Notruf, dann Erste Hilfe. Fotos und Meldung kommen später.","quelle":"§ 34 StVO","lc":true,"lek":"unfaelle","sg":"4.2"},{"id":"uf-02","typ":"tf","frage":"Wer nach einem kleinen Parkrempler nur einen Zettel mit seiner Telefonnummer hinterlässt und sofort weiterfährt, kann sich wegen Unfallflucht strafbar machen.","richtig":true,"erklaerung":"Ein Zettel ersetzt nicht das Warten einer angemessenen Zeit bzw. die Benachrichtigung der Polizei.","quelle":"§ 142 StGB","lc":true,"lek":"unfaelle","sg":"4.2"},{"id":"uf-03","typ":"single","frage":"Ein angestellter Fahrer verletzt sich bei einem Unfall und ist 2 Wochen krankgeschrieben. Was muss der Unternehmer tun?","optionen":["Nichts, die Krankenkasse regelt alles.","Den Arbeitsunfall innerhalb von 3 Tagen der Berufsgenossenschaft anzeigen.","Den Unfall innerhalb eines Monats der IHK melden.","Nur die Kfz-Versicherung informieren."],"richtig":1,"erklaerung":"Anzeigepflicht bei Tod oder mehr als 3 Tagen Arbeitsunfähigkeit, Frist 3 Tage ab Kenntnis.","quelle":"§ 193 SGB VII","lc":true,"lek":"unfaelle","sg":"4.2"},{"id":"uf-04","typ":"multi","frage":"Welche Maßnahmen schützen Taxifahrer vor Überfällen? Wähle alle richtigen.","optionen":["Alarmanlage, vom Fahrersitz auslösbar","Wenig Bargeld im Fahrzeug, Kartenzahlung fördern","Notruf-Funktion mit Ortung über die Zentrale","Fahrer sollen sich gegen Täter wehren","Möglichst viel Wechselgeld mitnehmen"],"richtig":[0,1,2],"erklaerung":"Bei einem Überfall gilt: Eigene Sicherheit geht vor, nicht wehren.","quelle":"§ 25 BOKraft, Unfallverhütung","lc":true,"lek":"unfaelle","sg":"4.2"},{"id":"uf-05","typ":"single","frage":"Welche Vorschrift der Berufsgenossenschaft enthält die „Grundsätze der Prävention“, z. B. Gefährdungsbeurteilung und Unterweisung?","optionen":["DGUV Vorschrift 1","DGUV Vorschrift 70","BOKraft","StVZO"],"richtig":0,"erklaerung":"DGUV Vorschrift 1 = Grundsätze der Prävention. DGUV Vorschrift 70 = Fahrzeuge.","quelle":"DGUV Vorschrift 1","lek":"unfaelle","sg":"4.2"},{"id":"uf-06","typ":"tf","frage":"Wer bei einem Unfall keine Erste Hilfe leistet, obwohl es ihm zumutbar wäre, macht sich strafbar.","richtig":true,"erklaerung":"Unterlassene Hilfeleistung nach § 323c StGB.","quelle":"§ 323c StGB","lek":"unfaelle","sg":"4.2"},{"id":"uf-07","typ":"offen","frage":"In Ihrem Betrieb gab es innerhalb von drei Monaten zwei Auffahrunfälle in der Nachtschicht. Welche Maßnahmen ergreifen Sie, damit sich das nicht wiederholt?","muster":"<p>Analyse: Uhrzeit, Schichtlänge, Pausen, Fahrer, Wetter, Fahrzeugzustand. Maßnahmen: technisch (Notbremsassistent, Reifen, Bremsen prüfen), organisatorisch (Schichtlängen begrenzen, Pausen nach ArbZG sicherstellen, Ruhezeiten einhalten, Touren planen), persönlich (Unterweisung zu Abstand, Müdigkeit, Ablenkung; Fahrsicherheitstraining). Unterweisung dokumentieren, Wirkung kontrollieren, Unfallstatistik führen. Meldungen an Versicherung und ggf. BG.</p>","punkte_liste":[{"t":"Ursachenanalyse","p":1},{"t":"Organisatorische Maßnahme (Schicht, Pausen, Ruhezeit)","p":1},{"t":"Persönliche Maßnahme (Unterweisung, Training)","p":1},{"t":"Technische Maßnahme oder Kontrolle der Wirksamkeit","p":1}],"quelle":"DGUV Vorschrift 1, ArbSchG","lek":"unfaelle","sg":"4.2"},{"id":"ug-01","typ":"zuordnung","frage":"Wie haften die Beteiligten? Ordne zu.","kategorien":["unbeschränkt","beschränkt"],"paare":[{"t":"Einzelunternehmer","k":0,"w":"Er haftet mit seinem ganzen Vermögen, auch privat."},{"t":"Gesellschafter einer GbR","k":0,"w":"Jeder haftet persönlich und unbeschränkt."},{"t":"Gesellschafter einer OHG","k":0,"w":"Alle haften unbeschränkt."},{"t":"Komplementär einer KG","k":0,"w":"Der Komplementär haftet unbeschränkt."},{"t":"Kommanditist einer KG","k":1,"w":"Er haftet nur bis zur Höhe seiner Einlage."},{"t":"Gesellschafter einer GmbH","k":1,"w":"Es haftet nur das Gesellschaftsvermögen."}],"erklaerung":"Unbeschränkte Haftung bedeutet: auch mit dem Privatvermögen.","quelle":"§ 705 BGB, §§ 105, 161 HGB, GmbHG","lc":true,"lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-02","typ":"single","frage":"Wie viel des Stammkapitals einer GmbH muss mindestens eingezahlt sein, bevor sie zum Handelsregister angemeldet wird?","optionen":["1 €","6.250 €","12.500 €","25.000 €"],"fest":true,"richtig":2,"erklaerung":"Auf jeden Anteil mindestens ein Viertel, insgesamt mindestens die Hälfte des Mindeststammkapitals von 25.000 €.","quelle":"§§ 5, 7 Abs. 2 GmbHG","lc":true,"lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-03","typ":"multi","frage":"Was gilt für die UG (haftungsbeschränkt)? Wähle alle richtigen.","optionen":["Das Stammkapital kann unter 25.000 € liegen.","Das Kapital muss vor der Anmeldung voll eingezahlt sein.","Sacheinlagen sind verboten.","Ein Viertel des Jahresüberschusses muss in eine Rücklage.","Die Gesellschafter haften unbeschränkt."],"richtig":[0,1,2,3],"erklaerung":"Die UG ist eine GmbH mit weniger Kapital. Die Gesellschafter haften nicht persönlich.","quelle":"§ 5a GmbHG","lc":true,"lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-04","typ":"single","frage":"Wo meldet ein Taxiunternehmer sein Gewerbe an?","optionen":["Bei der IHK","Beim Gewerbeamt der Gemeinde","Beim Amtsgericht","Bei der Genehmigungsbehörde nach PBefG, das reicht"],"richtig":1,"erklaerung":"Die Gewerbeanzeige geht an die zuständige Behörde der Gemeinde (Gewerbeamt). Sie ist zusätzlich zur PBefG-Genehmigung nötig.","quelle":"§ 14 GewO","lc":true,"lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-05","typ":"single","frage":"Innerhalb welcher Frist muss ein neues Unternehmen der Berufsgenossenschaft angezeigt werden?","optionen":["1 Woche nach Beginn","1 Monat nach Beginn","3 Monate nach Beginn","Erst, wenn der erste Unfall passiert"],"richtig":0,"erklaerung":"Binnen einer Woche nach Beginn des Unternehmens.","quelle":"§ 192 Abs. 1 SGB VII","lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-06","typ":"tf","frage":"Jeder Gewerbetreibende ist Kaufmann im Sinne des HGB, auch wenn sein Betrieb keinen kaufmännisch eingerichteten Geschäftsbetrieb braucht.","richtig":false,"erklaerung":"Kleingewerbetreibende, deren Betrieb nach Art oder Umfang keinen kaufmännischen Geschäftsbetrieb erfordert, sind keine Kaufleute. Sie können sich freiwillig eintragen lassen (§ 2 HGB).","quelle":"§ 1 Abs. 2 HGB","lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-07","typ":"single","frage":"Was bedeutet der Zusatz „e. K.“ hinter einem Firmennamen?","optionen":["Eingetragene Kapitalgesellschaft","Eingetragener Kaufmann (Einzelunternehmer im Handelsregister)","Europäische Kooperation","Ehemaliger Konzessionär"],"richtig":1,"erklaerung":"Einzelkaufleute im Handelsregister führen den Zusatz „eingetragener Kaufmann“ bzw. „e. K.“.","quelle":"§ 19 HGB","lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-08","typ":"single","frage":"Wer bekommt bei einer Taxi-GmbH die Genehmigung nach dem PBefG?","optionen":["Jeder Fahrer","Die GmbH als Unternehmer; die fachliche Eignung muss eine Person haben, die die Geschäfte führt","Nur der größte Gesellschafter persönlich","Die IHK"],"richtig":1,"erklaerung":"Unternehmer ist die Gesellschaft. Fachlich geeignet muss der Antragsteller oder die zur Führung der Geschäfte bestellte Person sein.","quelle":"§ 13 Abs. 1 Nr. 3 PBefG","lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-09","typ":"tf","frage":"Eine GmbH ist immer Kaufmann, auch wenn sie nur ein einziges Taxi betreibt.","richtig":true,"erklaerung":"Kapitalgesellschaften sind Formkaufleute.","quelle":"§ 6 HGB, § 13 Abs. 3 GmbHG","lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-10","typ":"single","frage":"Was kann die Behörde tun, wenn ein Gewerbetreibender unzuverlässig ist?","optionen":["Nichts, solange er Steuern zahlt","Das Gewerbe ganz oder teilweise untersagen","Nur eine Verwarnung aussprechen","Den Betrieb an die IHK übergeben"],"richtig":1,"erklaerung":"Gewerbeuntersagung wegen Unzuverlässigkeit.","quelle":"§ 35 GewO","lek":"unternehmen-gruenden","sg":"1.2"},{"id":"ug-11","typ":"offen","frage":"Zwei Freunde wollen gemeinsam einen Mietwagenbetrieb mit 6 Fahrzeugen gründen und möchten nicht mit ihrem Privatvermögen haften. Welche Rechtsform empfehlen Sie? Begründen Sie und nennen Sie die Kapitalanforderungen.","muster":"<p>Empfehlung: GmbH (oder UG, wenn wenig Kapital vorhanden ist). Begründung: Bei der GmbH haftet nur das Gesellschaftsvermögen, nicht das Privatvermögen der Gesellschafter. GbR oder OHG kommen nicht in Frage, weil dort alle unbeschränkt haften. Kapital: GmbH mindestens 25.000 € Stammkapital, bei Anmeldung mindestens 12.500 € eingezahlt (ein Viertel je Anteil). UG: unter 25.000 € möglich, aber voll in Geld einzuzahlen, keine Sacheinlagen, jährlich ein Viertel des Überschusses in die Rücklage. Gründung beim Notar, Eintragung ins Handelsregister. Hinweis: Für die Genehmigung zusätzlich 2.250 € + 5 × 1.250 € = 8.500 € Eigenkapital und Reserven nachweisen.</p>","punkte_liste":[{"t":"GmbH oder UG empfohlen","p":1},{"t":"Begründung: Haftung nur mit Gesellschaftsvermögen; GbR/OHG haften unbeschränkt","p":1},{"t":"GmbH: 25.000 € Stammkapital, mind. 12.500 € eingezahlt","p":1},{"t":"UG: voll einzahlen, keine Sacheinlagen, Rücklage","p":1},{"t":"Notar und Handelsregister (oder Eigenkapital 8.500 € nach PBZugV)","p":1}],"quelle":"GmbHG, HGB, PBZugV","lek":"unternehmen-gruenden","sg":"1.2"},{"id":"vk-01","typ":"single","frage":"Wer muss nach DGUV Vorschrift 70 vor Beginn jeder Schicht die Sicherheitseinrichtungen des Fahrzeugs prüfen?","optionen":["Die Werkstatt","Der Fahrer","Der TÜV","Die Berufsgenossenschaft"],"richtig":1,"erklaerung":"Der Fahrzeugführer prüft vor jeder Schicht und meldet Mängel. Mindestens einmal jährlich prüft zusätzlich ein Sachkundiger.","quelle":"§§ 36, 57 DGUV Vorschrift 70","lc":true,"lek":"verkehrssicherheit","sg":"4.1"},{"id":"vk-02","typ":"zahl","frage":"Wie lang ist der Anhalteweg bei 60 km/h und normaler Bremsung nach den Faustformeln?","richtig":54,"einheit":"m","tol":0.1,"dez":0,"loesung":"Reaktionsweg = 6 × 3 = 18 m\nBremsweg = 6 × 6 = 36 m\nAnhalteweg = 18 + 36 = 54 m","erklaerung":"Reaktionsweg (v/10)×3 plus Bremsweg (v/10)².","quelle":"Fahrschul-Faustformeln","lc":true,"lek":"verkehrssicherheit","sg":"4.1"},{"id":"vk-03","typ":"single","frage":"Wie oft muss ein Arbeitgeber seine Fahrer mindestens über Sicherheit und Gesundheitsschutz unterweisen?","optionen":["Nur bei der Einstellung","Mindestens einmal jährlich","Alle 5 Jahre","Nur nach einem Unfall"],"richtig":1,"erklaerung":"Bei Einstellung, bei Veränderungen und mindestens einmal jährlich; dokumentieren.","quelle":"§ 12 ArbSchG, § 4 DGUV Vorschrift 1","lc":true,"lek":"verkehrssicherheit","sg":"4.1"},{"id":"vk-04","typ":"zahl","frage":"Wie lang ist der Bremsweg bei einer Gefahrbremsung aus 80 km/h nach der Faustformel?","richtig":32,"einheit":"m","tol":0.1,"dez":0,"loesung":"(80 ÷ 10)² ÷ 2 = 64 ÷ 2 = 32 m","erklaerung":"Gefahrbremsung: halber normaler Bremsweg.","quelle":"Fahrschul-Faustformeln","lek":"verkehrssicherheit","sg":"4.1"},{"id":"vk-05","typ":"tf","frage":"Verdoppelt sich die Geschwindigkeit, verdoppelt sich auch der Bremsweg.","richtig":false,"erklaerung":"Der Bremsweg wächst mit dem Quadrat der Geschwindigkeit: doppelt so schnell = vierfacher Bremsweg.","quelle":"Fahrphysik","lek":"verkehrssicherheit","sg":"4.1"},{"id":"vk-06","typ":"single","frage":"Wie oft muss der Unternehmer seine Fahrzeuge nach DGUV Vorschrift 70 mindestens durch einen Sachkundigen prüfen lassen?","optionen":["Monatlich","Mindestens einmal jährlich","Alle 3 Jahre","Nie, die HU reicht"],"richtig":1,"erklaerung":"Bei Bedarf, mindestens einmal jährlich, mit schriftlichem Ergebnis.","quelle":"§ 57 DGUV Vorschrift 70","lek":"verkehrssicherheit","sg":"4.1"},{"id":"vk-07","typ":"offen","frage":"Erstellen Sie eine Anweisung für Ihre Fahrer zur Abfahrtkontrolle. Nennen Sie mindestens sechs Prüfpunkte.","muster":"<ul><li>Reifen: Luftdruck, Profil, Schäden</li><li>Beleuchtung, Blinker, Bremslichter</li><li>Bremse und Feststellbremse</li><li>Lenkung, Hupe, Scheibenwischer</li><li>Spiegel, Scheiben</li><li>Warnleuchten im Display</li><li>Ausrüstung: Verbandkasten, Warndreieck, Warnweste, Kindersitze</li><li>Taxameter, Taxischild, Alarmanlage, Papiere</li><li>Mängel sofort melden; bei Sicherheitsmängeln nicht losfahren</li></ul>","punkte_liste":[{"t":"Reifen und Beleuchtung","p":1},{"t":"Bremse, Lenkung, Sicht (Spiegel/Scheiben/Wischer)","p":1},{"t":"Ausrüstung und Papiere","p":1},{"t":"Taxispezifisch (Taxameter, Schild, Alarmanlage, Kindersitze)","p":1},{"t":"Mängel melden / nicht losfahren","p":1}],"quelle":"DGUV Vorschrift 70, DGUV Grundsatz 314-002","lek":"verkehrssicherheit","sg":"4.1"},{"id":"vs-01","typ":"multi","frage":"Welche Versicherungen sind für einen Taxiunternehmer mit einem angestellten Fahrer Pflicht? Wähle alle richtigen.","optionen":["Kfz-Haftpflichtversicherung","Gesetzliche Unfallversicherung bei der Berufsgenossenschaft","Sozialversicherung für den angestellten Fahrer","Vollkaskoversicherung","Rechtsschutzversicherung"],"richtig":[0,1,2],"erklaerung":"Kasko und Rechtsschutz sind freiwillig (Vollkasko kann aber vom Leasinggeber oder der Bank verlangt werden).","quelle":"PflVG, SGB VII, SGB IV","lc":true,"lek":"versicherungen","sg":"2.6"},{"id":"vs-02","typ":"single","frage":"Wie hoch ist die gesetzliche Mindestversicherungssumme der Kfz-Haftpflicht für Personenschäden je Unfall (Pkw)?","optionen":["1,3 Mio. €","5 Mio. €","7,5 Mio. €","100 Mio. €"],"fest":true,"richtig":2,"erklaerung":"7,5 Mio. € Personenschäden, 1,3 Mio. € Sachschäden, 50.000 € reine Vermögensschäden.","quelle":"Anlage zu § 4 Abs. 2 PflVG","lc":true,"lek":"versicherungen","sg":"2.6"},{"id":"vs-03","typ":"single","frage":"Ein Taxifahrer verursacht selbst einen Unfall. Sein eigenes Taxi ist schwer beschädigt. Welche Versicherung zahlt den Schaden am eigenen Fahrzeug?","optionen":["Die eigene Kfz-Haftpflicht","Die Vollkaskoversicherung","Die Berufsgenossenschaft","Die Teilkasko"],"richtig":1,"erklaerung":"Selbst verschuldete Unfallschäden am eigenen Fahrzeug zahlt nur die Vollkasko. Die Haftpflicht zahlt Schäden anderer.","quelle":"Versicherungswesen","lc":true,"lek":"versicherungen","sg":"2.6"},{"id":"vs-04","typ":"single","frage":"Ein Unternehmer lässt einen Fahrer ohne Fahrerlaubnis fahren. Es kommt zum Unfall. Was gilt in der Kfz-Haftpflicht?","optionen":["Die Versicherung zahlt dem Geschädigten nichts.","Die Versicherung zahlt dem Geschädigten und kann beim Unternehmer bis zu 5.000 € zurückfordern.","Die Versicherung zahlt und kann alles unbegrenzt zurückfordern.","Der Geschädigte muss sich an die BG wenden."],"richtig":1,"erklaerung":"Obliegenheitsverletzung vor dem Versicherungsfall: Leistungsfreiheit gegenüber dem Versicherungsnehmer begrenzt auf 5.000 €. Der Geschädigte ist geschützt.","quelle":"§ 5 KfzPflVV","lc":true,"lek":"versicherungen","sg":"2.6"},{"id":"vs-05","typ":"tf","frage":"Ein Mietwagen darf mit einer normalen Privat-Pkw-Versicherung gefahren werden, wenn er nur selten Fahrgäste befördert.","richtig":false,"erklaerung":"Die Verwendung als Mietwagen muss im Vertrag vereinbart sein. Sonst ist das eine Obliegenheitsverletzung (Verwendungsklausel) mit Regress.","quelle":"§ 5 Abs. 1 Nr. 1 KfzPflVV","lc":true,"lek":"versicherungen","sg":"2.6"},{"id":"vs-06","typ":"single","frage":"Welche Versicherung zahlt, wenn ein Fahrgast im Büro des Taxiunternehmens über ein Kabel stolpert und sich verletzt?","optionen":["Kfz-Haftpflicht","Betriebshaftpflicht","Teilkasko","Krankentagegeldversicherung"],"richtig":1,"erklaerung":"Schäden außerhalb des Fahrbetriebs deckt die Betriebshaftpflicht.","quelle":"Versicherungswesen","lek":"versicherungen","sg":"2.6"},{"id":"vs-07","typ":"single","frage":"Was deckt die Teilkasko typischerweise?","optionen":["Selbst verschuldete Unfälle","Diebstahl, Brand, Glasbruch, Sturm, Hagel, Wildunfall","Schäden an fremden Autos","Verdienstausfall"],"richtig":1,"erklaerung":"Vollkasko deckt zusätzlich selbst verschuldete Unfälle und Vandalismus.","quelle":"Versicherungswesen","lek":"versicherungen","sg":"2.6"},{"id":"vs-08","typ":"tf","frage":"Ein Geschädigter kann seinen Anspruch direkt gegen die Kfz-Haftpflichtversicherung des Unfallverursachers geltend machen.","richtig":true,"erklaerung":"Direktanspruch nach § 115 VVG.","quelle":"§ 115 VVG","lek":"versicherungen","sg":"2.6"},{"id":"vs-09","typ":"offen","frage":"Welche Versicherungen empfehlen Sie einem Existenzgründer mit einem Mietwagen, der selbst fährt? Unterscheiden Sie Pflicht- und freiwillige Versicherungen.","muster":"<p><b>Pflicht:</b> Kfz-Haftpflicht (Verwendung als Mietwagen), gesetzliche Unfallversicherung bei der BG Verkehr, Krankenversicherung (mit Pflegeversicherung). <b>Freiwillig, empfehlenswert:</b> Voll- oder Teilkasko (bei Finanzierung/Leasing oft Pflicht), Fahrerschutz, Betriebshaftpflicht, Rechtsschutz, Betriebsunterbrechung, Krankentagegeld, Berufsunfähigkeit, Altersvorsorge.</p>","punkte_liste":[{"t":"Kfz-Haftpflicht als Pflicht (mit richtiger Verwendung)","p":1},{"t":"BG-Unfallversicherung und Krankenversicherung als Pflicht","p":1},{"t":"Mindestens zwei sinnvolle betriebliche freiwillige Versicherungen","p":1},{"t":"Mindestens eine persönliche Absicherung (Krankentagegeld, BU, Rente)","p":1}],"quelle":"Versicherungswesen","lek":"versicherungen","sg":"2.6"},{"id":"vh-01","typ":"zuordnung","frage":"Welcher Vertragstyp liegt vor?","kategorien":["Kauf","Miete","Werkvertrag","Darlehen"],"paare":[{"t":"Ein Fahrgast lässt sich zum Bahnhof fahren.","k":2,"w":"Beförderungsvertrag = Werkvertrag (Erfolg geschuldet)."},{"t":"Der Unternehmer kauft beim Händler ein neues Taxi.","k":0,"w":"Kaufvertrag nach § 433 BGB."},{"t":"Der Unternehmer mietet eine Garage für 120 € im Monat.","k":1,"w":"Mietvertrag nach § 535 BGB."},{"t":"Die Bank leiht dem Unternehmer 30.000 € für 4 Jahre.","k":3,"w":"Darlehensvertrag nach § 488 BGB."},{"t":"Die Werkstatt repariert das Getriebe.","k":2,"w":"Reparatur = Werkvertrag."}],"erklaerung":"Werkvertrag: Erfolg geschuldet. Dienstvertrag: nur die Tätigkeit.","quelle":"BGB","lc":true,"lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-02","typ":"single","frage":"Ein Taxiunternehmer hängt ein Schild ins Taxi: „Keine Haftung für Personenschäden.“ Ist das wirksam?","optionen":["Ja, wenn der Fahrgast es gesehen hat","Nein, bei entgeltlicher geschäftsmäßiger Personenbeförderung darf die Haftung für Tod und Verletzung von Fahrgästen weder ausgeschlossen noch beschränkt werden.","Ja, bis 1.000 €","Nur bei Fahrten über 50 km"],"richtig":1,"erklaerung":"§ 8a StVG verbietet den Ausschluss und die Beschränkung der Halterhaftung gegenüber beförderten Personen.","quelle":"§ 8a StVG","lc":true,"lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-03","typ":"zahl","frage":"Durch einen leicht fahrlässigen Fahrfehler wird der Laptop eines Fahrgasts zerstört (Wert 1.800 €). Der Unternehmer hat die Haftung für Sachschäden so weit wie gesetzlich zulässig ausgeschlossen. Wie viel muss er ersetzen?","richtig":1000,"einheit":"€","tol":0,"loesung":"Ausschluss nur für den Teil über 1.000 € → Ersatz: 1.000 €","erklaerung":"Der Haftungsausschluss für Sachschäden ist nur für den Betrag über 1.000 € möglich, und nicht bei Vorsatz oder grober Fahrlässigkeit.","quelle":"§ 23 PBefG","lc":true,"lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-04","typ":"single","frage":"Ein Taxifahrer findet nach der Fahrt ein Handy im Wert von 600 € auf dem Rücksitz. Was gilt?","optionen":["Er darf es behalten, wenn sich niemand meldet.","Er muss es unverzüglich beim Unternehmer oder der bestimmten Stelle abgeben. Finderlohn bekommt er als Mitarbeiter nicht.","Er bekommt 10 % Finderlohn.","Er muss es zur IHK bringen."],"richtig":1,"erklaerung":"§ 11 BOKraft: Pflicht zur Prüfung und Abgabe. § 978 BGB: Mitarbeiter des Verkehrsunternehmens haben keinen Anspruch auf Finderlohn.","quelle":"§ 11 BOKraft, § 978 BGB","lc":true,"lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-05","typ":"single","frage":"Welcher Vertragstyp ist der Beförderungsvertrag?","optionen":["Kaufvertrag","Mietvertrag","Werkvertrag","Dienstvertrag"],"richtig":2,"erklaerung":"Geschuldet wird der Erfolg: die Beförderung ans Ziel.","quelle":"§ 631 BGB","lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-06","typ":"tf","frage":"Der Halter eines Taxis haftet für Schäden aus dem Betrieb des Fahrzeugs auch dann, wenn weder er noch der Fahrer Schuld hat.","richtig":true,"erklaerung":"Halterhaftung ist Gefährdungshaftung. Ausgeschlossen ist sie nur bei höherer Gewalt.","quelle":"§ 7 StVG","lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-07","typ":"single","frage":"Wie hoch ist der Höchstbetrag der Halterhaftung für Personenschäden bei einem Unfall (ohne Sonderfälle)?","optionen":["1 Mio. €","2,5 Mio. €","5 Mio. €","unbegrenzt"],"fest":true,"richtig":2,"erklaerung":"5 Mio. € für Personenschäden, 1 Mio. € für Sachschäden je Ereignis. Bei Verschulden nach § 823 BGB gibt es keine Grenze.","quelle":"§ 12 StVG","lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-08","typ":"tf","frage":"Ein Fahrgast, der im Taxi ein Portemonnaie mit 300 € findet, kann einen halbierten Finderlohn verlangen.","richtig":true,"erklaerung":"Ab einem Wert von 50 € hat der Finder (der kein Mitarbeiter ist) Anspruch auf Finderlohn in halber Höhe des normalen Satzes, wenn er die Sache ordnungsgemäß abgibt.","quelle":"§ 978 Abs. 2 BGB","lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-09","typ":"single","frage":"Eine Taxirechnung aus einer Firmenfahrt vom 10. März 2026 wird nicht bezahlt. Wann verjährt die Forderung?","optionen":["10. März 2027","31. Dezember 2027","31. Dezember 2029","10. März 2036"],"richtig":2,"erklaerung":"Regelmäßige Verjährung 3 Jahre, Beginn am Schluss des Jahres der Entstehung: 31.12.2026 + 3 Jahre = 31.12.2029.","quelle":"§§ 195, 199 BGB","lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-10","typ":"single","frage":"Ein 9-jähriges Kind steigt allein ins Taxi und will nach Hause fahren. Wie ist die rechtliche Lage?","optionen":["Das Kind ist voll geschäftsfähig.","Das Kind ist beschränkt geschäftsfähig. Der Vertrag ist wirksam, wenn die Eltern zustimmen oder es mit eigenen Mitteln (Taschengeld) bezahlt.","Kinder dürfen nie Taxi fahren.","Das Kind ist geschäftsunfähig, der Vertrag ist immer nichtig."],"richtig":1,"erklaerung":"7 bis 17 Jahre: beschränkt geschäftsfähig (§§ 106 ff. BGB), Taschengeldparagraph § 110 BGB.","quelle":"§§ 106, 107, 110 BGB","lek":"vertraege-haftung","sg":"1.6"},{"id":"vh-11","typ":"offen","frage":"Ein Taxi verunglückt unverschuldet, weil ein anderes Auto die Vorfahrt missachtet. Ein Fahrgast wird verletzt, sein Gepäck beschädigt. Erläutern Sie die Haftung gegenüber dem Fahrgast.","muster":"<p>Der Halter des Taxis haftet gegenüber dem Fahrgast nach § 7 StVG auch ohne Verschulden (Gefährdungshaftung), außer bei höherer Gewalt. Bei entgeltlicher Beförderung darf die Haftung für Personenschäden nicht ausgeschlossen werden (§ 8a StVG). Für Sachschäden kann sie nur für den Teil über 1.000 € ausgeschlossen werden (§ 23 PBefG). Auch der Unfallverursacher und dessen Halter haften (§§ 7, 18 StVG, § 823 BGB). Die Kfz-Haftpflichtversicherungen regulieren den Schaden; Haftungsquoten werden zwischen den Beteiligten ausgeglichen.</p>","punkte_liste":[{"t":"Halterhaftung des Taxis ohne Verschulden (§ 7 StVG)","p":1},{"t":"Kein Ausschluss bei Personenschäden (§ 8a StVG)","p":1},{"t":"Sachschäden: Ausschluss nur über 1.000 € (§ 23 PBefG)","p":1},{"t":"Haftung des Unfallverursachers / Versicherung","p":1}],"quelle":"StVG, PBefG, BGB","lek":"vertraege-haftung","sg":"1.6"},{"id":"wh-01","typ":"single","frage":"In welchen Abständen muss ein Taxi zur Hauptuntersuchung?","optionen":["Alle 6 Monate","Alle 12 Monate","Alle 24 Monate","Alle 36 Monate"],"fest":true,"richtig":1,"erklaerung":"Pkw zur Personenbeförderung nach PBefG: 12 Monate.","quelle":"§ 29 StVZO, Anlage VIII","lc":true,"lek":"wartung-hu","sg":"3.2"},{"id":"wh-02","typ":"zuordnung","frage":"Wie oft muss geeicht bzw. geprüft werden?","kategorien":["jedes Jahr","alle 2 Jahre"],"paare":[{"t":"Fahrpreisanzeiger (Taxameter)","k":0,"w":"Eichfrist 1 Jahr."},{"t":"Wegstreckenzähler im Mietwagen","k":1,"w":"Eichfrist 2 Jahre."},{"t":"Hauptuntersuchung Taxi","k":0,"w":"12 Monate."},{"t":"Hauptuntersuchung Mietwagen","k":0,"w":"Auch Mietwagen nach PBefG: 12 Monate."}],"erklaerung":"Nicht verwechseln: HU (StVZO) und Eichung (Eichrecht) sind verschiedene Prüfungen.","quelle":"StVZO Anlage VIII, MessEV","lc":true,"lek":"wartung-hu","sg":"3.2"},{"id":"wh-03","typ":"multi","frage":"Wann muss ein Taxameter vor Ablauf der Eichfrist neu geeicht werden? Wähle alle richtigen.","optionen":["Nach einer Reparatur am Gerät","Nach einer Neuprogrammierung wegen Tarifänderung","Nach Einbau in ein anderes Fahrzeug","Nach jeder Ölwechsel-Inspektion","Wenn der Fahrer wechselt"],"richtig":[0,1,2],"erklaerung":"Jeder Eingriff in das Messgerät oder seine Anpassung an das Fahrzeug erfordert eine neue Eichung.","quelle":"Eichrecht","lc":true,"lek":"wartung-hu","sg":"3.2"},{"id":"wh-04","typ":"tf","frage":"Bei der Hauptuntersuchung eines Taxis wird auch geprüft, ob das Fahrzeug den Vorschriften der BOKraft entspricht.","richtig":true,"erklaerung":"§ 41 BOKraft.","quelle":"§ 41 BOKraft","lek":"wartung-hu","sg":"3.2"},{"id":"wh-05","typ":"single","frage":"Wer eicht Taxameter?","optionen":["Die IHK","Das Eichamt des Landes","Jede Kfz-Werkstatt","Die Genehmigungsbehörde"],"richtig":1,"erklaerung":"Eichung ist Aufgabe der Eichbehörden der Länder.","quelle":"Mess- und Eichgesetz","lek":"wartung-hu","sg":"3.2"},{"id":"wh-06","typ":"offen","frage":"Stellen Sie einen Wartungsplan für ein Taxi mit 80.000 km Fahrleistung im Jahr auf. Nennen Sie mindestens fünf Maßnahmen mit Zeitpunkt.","muster":"<ul><li>Vor jeder Schicht: Abfahrtkontrolle (Licht, Reifen, Bremsen, Ausrüstung, Taxameter)</li><li>Wöchentlich: Reifendruck, Flüssigkeiten, Reinigung</li><li>Inspektion nach Herstellerangabe, bei 80.000 km mehrmals im Jahr</li><li>Reifenwechsel Sommer/Winter, Kontrolle Profiltiefe</li><li>Jährlich: HU mit AU, Bericht an Genehmigungsbehörde</li><li>Jährlich: Eichung Taxameter</li><li>Wartungsheft mit km-Stand und nächsten Terminen</li></ul>","punkte_liste":[{"t":"Tägliche Abfahrtkontrolle","p":1},{"t":"Inspektion nach km/Herstellerangabe","p":1},{"t":"Jährliche HU","p":1},{"t":"Jährliche Eichung Taxameter","p":1},{"t":"Weitere sinnvolle Maßnahme (Reifen, Wartungsheft …)","p":1}],"quelle":"StVZO, BOKraft, MessEV","lek":"wartung-hu","sg":"3.2"},{"id":"zf-01","typ":"single","frage":"Ein Kunde lässt eine SEPA-Basislastschrift zurückbuchen. Bis wann ist das ohne Angabe von Gründen möglich, wenn ein Mandat vorlag?","optionen":["5 Tage","8 Wochen","13 Monate","Gar nicht"],"fest":true,"richtig":1,"erklaerung":"8 Wochen nach Belastung bei autorisierter Basislastschrift. Ohne Mandat: bis 13 Monate. Firmenlastschrift: keine Rückgabe.","quelle":"§§ 675x, 676b BGB","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-02","typ":"single","frage":"Ein Taxiunternehmer finanziert sein Fahrzeug über die Bank. Die Bank wird Eigentümerin, er darf das Taxi weiter fahren. Die Bank behält die Zulassungsbescheinigung Teil II. Wie heißt diese Sicherheit?","optionen":["Bürgschaft","Grundschuld","Sicherungsübereignung","Eigentumsvorbehalt"],"richtig":2,"erklaerung":"Bei der Sicherungsübereignung wird die Bank Eigentümerin, der Unternehmer bleibt Besitzer.","quelle":"Kreditsicherheiten","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-03","typ":"multi","frage":"Welche Nachteile kann Leasing für ein Taxi haben? Wähle alle richtigen.","optionen":["Kilometerbegrenzung mit Nachzahlung bei Mehr-km","Meist insgesamt teurer als ein Barkauf","Nachzahlung für Schäden bei Rückgabe","Man braucht mehr Eigenkapital als beim Kauf","Die Raten sind steuerlich nie absetzbar"],"richtig":[0,1,2],"erklaerung":"Leasing braucht wenig Eigenkapital und die Raten sind Betriebsausgaben. Bei Taxis mit hoher Fahrleistung ist die km-Grenze ein wichtiges Thema.","quelle":"Finanzierung","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-04","typ":"zahl","frage":"Ein Unternehmer nutzt einen Kontokorrentkredit von 12.000 € für 60 Tage zu 9 % Zinsen. Wie viel Zinsen zahlt er (kaufmännisch, 360 Tage)?","richtig":180,"einheit":"€","loesung":"12.000 × 9 × 60 ÷ (100 × 360) = 180,00 €","erklaerung":"Zinsen = K × p × t ÷ (100 × 360).","quelle":"Zinsrechnung","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-05","typ":"zahl","frage":"Eine Werkstattrechnung über 2.400 € ist in 30 Tagen fällig. Bei Zahlung innerhalb von 10 Tagen gibt es 3 % Skonto. Wie hoch ist der Skonto-Jahreszins (Näherungsformel)?","richtig":54,"einheit":"%","tol":0.1,"dez":0,"loesung":"3 % × 360 ÷ (30 − 10) = 3 × 18 = 54 %","erklaerung":"Skonto zu nutzen lohnt sich fast immer.","quelle":"Skonto","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-06","typ":"zahl","frage":"Ein Betrieb hat 25.000 € Eigenkapital und 75.000 € Fremdkapital. Wie hoch ist die Eigenkapitalquote?","richtig":25,"einheit":"%","tol":0.1,"dez":0,"loesung":"Gesamtkapital = 25.000 + 75.000 = 100.000 €\n25.000 ÷ 100.000 × 100 = 25 %","erklaerung":"Eigenkapitalquote = Eigenkapital ÷ Gesamtkapital × 100.","quelle":"Kennzahlen","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-07","typ":"zahl","frage":"Flüssige Mittel 6.000 €, kurzfristige Forderungen 9.000 €, kurzfristige Verbindlichkeiten 12.000 €. Wie hoch ist die Liquidität 2. Grades?","richtig":125,"einheit":"%","tol":0.1,"dez":0,"loesung":"(6.000 + 9.000) ÷ 12.000 × 100 = 125 %","erklaerung":"Liquidität 2. Grades = (flüssige Mittel + kurzfristige Forderungen) ÷ kurzfristige Verbindlichkeiten. Über 100 % ist gut.","quelle":"Kennzahlen","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-08","typ":"zahl","frage":"Ein Mietwagenbetrieb macht 180.000 € Umsatz und 18.000 € Gewinn. Wie hoch ist die Umsatzrentabilität?","richtig":10,"einheit":"%","tol":0.1,"dez":0,"loesung":"18.000 ÷ 180.000 × 100 = 10 %","erklaerung":"Von 100 € Umsatz bleiben 10 € Gewinn.","quelle":"Kennzahlen","lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-09","typ":"single","frage":"Was ist ein Annuitätendarlehen?","optionen":["Darlehen mit gleich hoher Tilgung, die Rate sinkt","Darlehen mit gleich hoher Rate aus Zins und Tilgung; der Tilgungsanteil steigt","Darlehen, das am Ende in einer Summe zurückgezahlt wird","Kreditlinie auf dem Girokonto"],"richtig":1,"erklaerung":"Annuität = gleichbleibende Rate. Der Zinsanteil sinkt, der Tilgungsanteil steigt.","quelle":"Kreditarten","lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-10","typ":"tf","frage":"Seit Oktober 2025 dürfen Banken im Euroraum für Echtzeitüberweisungen nicht mehr verlangen als für normale Überweisungen.","richtig":true,"erklaerung":"Das schreibt die EU-Verordnung über Sofortzahlungen vor. Das Geld kommt in höchstens 10 Sekunden an.","quelle":"VO (EU) 2024/886","lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-11","typ":"single","frage":"Welcher Kredit eignet sich für kurzfristige Engpässe, zum Beispiel bis eine Krankenkasse ihre Sammelrechnung bezahlt?","optionen":["Kontokorrentkredit","Hypothek","Fälligkeitsdarlehen über 10 Jahre","Dokumentenkredit"],"richtig":0,"erklaerung":"Der Kontokorrentkredit ist flexibel, aber teuer. Er ist für kurzfristige Lücken gedacht.","quelle":"Kreditarten","lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-12","typ":"zahl","frage":"Ein Unternehmer hat 50.000 € Eigenkapital eingesetzt und 12.000 € Gewinn erzielt. Wie hoch ist die Eigenkapitalrentabilität?","richtig":24,"einheit":"%","tol":0.1,"dez":0,"loesung":"12.000 ÷ 50.000 × 100 = 24 %","erklaerung":"Eigenkapitalrentabilität = Gewinn ÷ Eigenkapital × 100.","quelle":"Kennzahlen","lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zf-13","typ":"offen","frage":"Ein Taxiunternehmer will ein neues Fahrzeug für 45.000 € anschaffen. Vergleichen Sie Kauf mit Bankkredit und Leasing. Nennen Sie je zwei Vor- und Nachteile.","muster":"<p><b>Kauf mit Kredit:</b> Vorteile: Fahrzeug gehört (nach Tilgung) dem Unternehmer, keine km-Begrenzung, Abschreibung steuerlich nutzbar, meist günstiger insgesamt. Nachteile: Bank verlangt Sicherheiten (Sicherungsübereignung) und Eigenkapital, Zins- und Tilgungslast, Restwertrisiko beim Unternehmer.</p><p><b>Leasing:</b> Vorteile: wenig Eigenkapital, planbare Raten, Raten als Betriebsausgaben, oft mit Service. Nachteile: insgesamt meist teurer, km-Begrenzung (bei Taxis kritisch), Nachzahlungen für Mehr-km und Schäden, Fahrzeug gehört nicht dem Unternehmer.</p>","punkte_liste":[{"t":"Zwei Vorteile Kauf/Kredit","p":1},{"t":"Zwei Nachteile Kauf/Kredit","p":1},{"t":"Zwei Vorteile Leasing","p":1},{"t":"Zwei Nachteile Leasing (z. B. km-Grenze)","p":1}],"quelle":"Finanzierung","lek":"zahlungsverkehr-finanzierung","sg":"2.1"},{"id":"zl-01","typ":"single","frage":"Welches Dokument gehört ins Fahrzeug, welches ins Büro?","optionen":["Teil I und Teil II gehören beide ins Fahrzeug.","Teil I (Fahrzeugschein) ins Fahrzeug, Teil II (Fahrzeugbrief) ins Büro.","Teil II ins Fahrzeug, Teil I ins Büro.","Beide gehören zur Zulassungsbehörde."],"richtig":1,"erklaerung":"Der Fahrzeugbrief ist der Nachweis der Verfügungsberechtigung und gehört sicher verwahrt, bei Finanzierung oft bei der Bank.","quelle":"FZV","lc":true,"lek":"zulassung","sg":"3.1"},{"id":"zl-02","typ":"multi","frage":"Was muss geschehen, bevor ein neu zugelassenes Fahrzeug als Taxi eingesetzt werden darf? Wähle alle richtigen.","optionen":["Eichung des Fahrpreisanzeigers im Fahrzeug","Hauptuntersuchung nach § 42 BOKraft mit Bericht an die Genehmigungsbehörde","Eintragung des Fahrzeugs (Kennzeichen) in die Genehmigung","Anmeldung bei der IHK","Abnahme durch die Polizei"],"richtig":[0,1,2],"erklaerung":"Vor dem ersten Einsatz: Ausrüstung, Eichung, BOKraft-Untersuchung, Eintragung in die Genehmigung und Ordnungsnummer.","quelle":"§ 42 BOKraft, § 17 PBefG","lc":true,"lek":"zulassung","sg":"3.1"},{"id":"zl-03","typ":"single","frage":"Ein Taxiunternehmer ersetzt ein altes Taxi durch ein neues. Was muss er gegenüber der Genehmigungsbehörde tun?","optionen":["Nichts, die Genehmigung gilt für den Unternehmer.","Die Genehmigungsurkunde zur Änderung vorlegen, damit das neue Fahrzeug eingetragen wird.","Eine komplett neue Genehmigung mit Anhörung beantragen.","Nur die Versicherung informieren."],"richtig":1,"erklaerung":"§ 17 Abs. 2 PBefG. Für den reinen Fahrzeugaustausch ist keine Anhörung nötig (§ 14 Abs. 3).","quelle":"§§ 14, 17 PBefG","lc":true,"lek":"zulassung","sg":"3.1"},{"id":"zl-04","typ":"single","frage":"Welche Behörde lässt Fahrzeuge zu?","optionen":["Die IHK","Die Zulassungsbehörde (Straßenverkehrsamt von Kreis oder kreisfreier Stadt)","Das Kraftfahrt-Bundesamt direkt","Die Genehmigungsbehörde nach PBefG"],"richtig":1,"erklaerung":"Zulassung: Zulassungsbehörde. Genehmigung nach PBefG: Genehmigungsbehörde. Das können zwei verschiedene Ämter sein.","quelle":"FZV","lek":"zulassung","sg":"3.1"},{"id":"zl-05","typ":"tf","frage":"Den Prüfbericht der Hauptuntersuchung muss der Taxiunternehmer unverzüglich der Genehmigungsbehörde (oder der vom Land bestimmten Stelle) vorlegen.","richtig":true,"erklaerung":"§ 41 BOKraft verlangt eine Abschrift des Untersuchungsberichts.","quelle":"§ 41 BOKraft","lek":"zulassung","sg":"3.1"},{"id":"zl-06","typ":"single","frage":"Was ist die eVB?","optionen":["Die elektronische Versicherungsbestätigung der Kfz-Haftpflicht, nötig für die Zulassung","Die Eichbescheinigung des Taxameters","Die Einkommensteuervorauszahlung","Ein Bußgeldbescheid"],"richtig":0,"erklaerung":"Ohne Nachweis der Kfz-Haftpflicht keine Zulassung.","quelle":"FZV, PflVG","lek":"zulassung","sg":"3.1"},{"id":"zl-07","typ":"offen","frage":"Beschreiben Sie die Schritte von der Anschaffung eines neuen Fahrzeugs bis zum ersten Einsatz als Mietwagen.","muster":"<p>Fahrzeug mit Typgenehmigung/COC kaufen; ausrüsten (Wegstreckenzähler mit TSE, Alarmanlage, keine Taxi-Kennzeichen); als Mietwagen versichern (eVB); bei der Zulassungsbehörde zulassen; Wegstreckenzähler eichen lassen; Hauptuntersuchung nach § 42 BOKraft vor dem ersten Einsatz, Bericht an die Genehmigungsbehörde; Fahrzeug in die Genehmigung eintragen lassen, Ordnungsnummer anbringen; Aufzeichnungssystem beim Finanzamt melden.</p>","punkte_liste":[{"t":"Ausrüstung (Wegstreckenzähler, Alarmanlage)","p":1},{"t":"Versicherung und Zulassung","p":1},{"t":"Eichung","p":1},{"t":"HU nach BOKraft mit Bericht an die Behörde","p":1},{"t":"Eintragung in die Genehmigung / Ordnungsnummer","p":1}],"quelle":"FZV, BOKraft, PBefG","lek":"zulassung","sg":"3.1"}];
